const config = {
  "previewFeatures": [],
  "clientVersion": "7.10.1",
  "engineVersion": "d1b3f377ca835d73fd50954a5e22128b9ebdd6b8",
  "activeProvider": "postgresql",
  "inlineSchema": "// Prisma schema — Logiqdev OS API\n//\n// Module coverage:\n//   01 Users, Members, Organizations, Branches & Permissions  → docs/features/01-users-organizations-permissions.md (LOG-406)\n//   02 CRM & Sales Management (incl. platform custom fields, tags, saved views) → docs/features/02-crm-sales-management.md (LOG-404)\n//   03 Proposals & Quotations (incl. platform number sequences) → docs/features/03-proposal-quotation-generator.md (LOG-303)\n//   04 Contracts (incl. e-signature provider abstraction) → docs/features/04-contracts.md (LOG-349)\n//   05 Project Management → docs/features/05-project-management.md (LOG-405)\n//   06 Task Management → docs/features/06-task-management.md (LOG-102)\n//\n// Conventions:\n//   - Table names snake_case plural via @@map; columns snake_case.\n//   - Primary keys are uuid strings; foreign keys end in _id.\n//   - Records that belong to a tenant carry organization_id (01 §9).\n//   - Tables owned by other modules (companies, projects, documents, …) are NOT defined here.\n//     Where 01 must point at them, the id is stored as a plain string without a relation\n//     and the owning spec is named in a comment.\n\ngenerator client {\n  provider = \"prisma-client-js\"\n  output   = \"../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// =====================================================================\n// Enums — 01 Users, Organizations & Permissions\n// =====================================================================\n\n/// Platform-level role (01 §64). Operates the SaaS itself; not an organization role.\nenum AuthRole {\n  USER\n  ADMIN\n  SUPER_ADMIN\n  SUPPORT\n}\n\n/// 01 §5\nenum UserStatus {\n  INVITED\n  PENDING_VERIFICATION\n  ACTIVE\n  SUSPENDED\n  LOCKED\n  DEACTIVATED\n}\n\n/// 01 §6, §74\nenum AuthMethodType {\n  PASSWORD\n  MAGIC_LINK\n  PASSKEY\n  OAUTH\n  SSO\n  TOTP\n  SMS_OTP\n  EMAIL_OTP\n  RECOVERY_CODES\n}\n\n/// 01 §10\nenum OrganizationStatus {\n  SETUP\n  ACTIVE\n  SUSPENDED\n  READ_ONLY\n  ARCHIVED\n  PENDING_DELETION\n  DELETED\n}\n\n/// 01 §19\nenum BranchStatus {\n  ACTIVE\n  PLANNED\n  TEMPORARILY_CLOSED\n  SUSPENDED\n  ARCHIVED\n}\n\n/// 01 §16, §119 — what the branch represents; never implies legal status.\nenum BranchKind {\n  OPERATIONAL\n  OFFICE\n  REGIONAL_UNIT\n  SUBSIDIARY_REFERENCE\n  SERVICE_CENTER\n  REMOTE\n}\n\n/// 01 §24, §77–79 — the nature of a membership.\nenum MembershipType {\n  INTERNAL\n  EXTERNAL_COLLABORATOR\n  GUEST\n}\n\n/// 01 §24 membership status\nenum MembershipStatus {\n  INVITED\n  ACTIVE\n  SUSPENDED\n  DEACTIVATED\n}\n\n/// 01 §41, §43\nenum TeamKind {\n  TEAM\n  DEPARTMENT\n  BUSINESS_UNIT\n  PROJECT_TEAM\n}\n\n/// 01 §45 — role types. CUSTOMER_PORTAL roles bundle portal.* permissions (01 §79).\nenum RoleType {\n  SYSTEM\n  ORGANIZATION\n  BRANCH\n  TEAM\n  PROJECT\n  CUSTOMER_PORTAL\n}\n\nenum RoleStatus {\n  DRAFT\n  PUBLISHED\n  DEPRECATED\n}\n\n/// 01 §22, §50 — where a role assignment or grant applies.\nenum ScopeType {\n  ORGANIZATION\n  BRANCH\n  BRANCH_HIERARCHY\n  TEAM\n  PROJECT\n  RESOURCE\n  CUSTOMER\n}\n\n/// 01 §53\nenum PermissionEffect {\n  ALLOW\n  DENY\n}\n\n/// 01 §56 — products that can be enabled per organization and per member.\nenum ModuleKey {\n  CRM\n  PROPOSALS\n  CONTRACTS\n  PROJECTS\n  TASKS\n  CUSTOMER_PORTAL\n  FINANCE\n  INCOME_EXPENSE\n  EMPLOYEES\n  COMMUNICATION\n  MESSAGING\n  SUPPORT\n  NOTIFICATIONS\n  BUSINESS_DOCS\n  DOCUMENTS\n  TIME_TRACKING\n  CALENDAR\n  AUTOMATION\n  ADMINISTRATION\n}\n\n/// 01 §66\nenum InvitationStatus {\n  PENDING\n  ACCEPTED\n  EXPIRED\n  CANCELLED\n  REJECTED\n}\n\n/// 01 §65, §67 — how a membership or invitation was provisioned.\nenum ProvisioningSource {\n  MANUAL\n  INVITATION_LINK\n  BULK_IMPORT\n  SSO\n  SCIM\n  API\n}\n\n/// 01 §69\nenum SsoProtocol {\n  SAML\n  OIDC\n}\n\n/// 01 §70\nenum DomainVerificationStatus {\n  PENDING\n  VERIFIED\n  FAILED\n  REVOKED\n}\n\n/// 01 §74\nenum MfaPolicy {\n  OPTIONAL\n  REQUIRED_FOR_ADMINS\n  REQUIRED_FOR_ALL\n  REQUIRED_FOR_SENSITIVE_MODULES\n}\n\n/// 01 §76\nenum ServiceAccountStatus {\n  ACTIVE\n  SUSPENDED\n  REVOKED\n}\n\n/// 01 §94\nenum DelegationStatus {\n  SCHEDULED\n  ACTIVE\n  EXPIRED\n  REVOKED\n}\n\n/// 01 §99–100, §139 — who performed an audited action.\nenum AuditActorType {\n  USER\n  SERVICE_ACCOUNT\n  SYSTEM\n  PLATFORM_ADMIN\n}\n\n/// Legacy enum used by the Document model. Documents are owned by\n/// docs/features/17-documents-file-management.md (LOG-407).\nenum DocumentType {\n  LOGO\n  BANNER\n  IMAGE\n  VIDEO\n  AUDIO\n  PDF\n  DOCUMENT\n  OTHER\n}\n\n// =====================================================================\n// Identity — 01 §4–7, §72, §74, §127\n// =====================================================================\n\n/// 01 §4 — a global human identity. Never tenant-scoped.\nmodel User {\n  id                      String     @id @default(uuid())\n  email                   String     @unique\n  phone                   String?    @unique\n  password                String\n  /// Platform-level role (01 §64). Organization permissions are modelled through Membership, not here.\n  role                    AuthRole   @default(USER)\n  status                  UserStatus @default(ACTIVE)\n  first_name              String?\n  last_name               String?\n  display_name            String?\n  profile_photo_url       String?\n  locale                  String?\n  timezone                String?\n  language                String?\n  email_verified_at       DateTime?\n  phone_verified_at       DateTime?\n  mfa_enabled             Boolean    @default(false)\n  last_login_at           DateTime?\n  /// 01 §127 — not permissions.\n  default_organization_id String?\n  deactivated_at          DateTime?\n  created_at              DateTime   @default(now())\n  updated_at              DateTime   @updatedAt\n\n  password_reset_tokens PasswordResetToken[]\n  auth_methods          UserAuthMethod[]\n  sessions              UserSession[]\n  preferences           UserPreference?\n  memberships           Membership[]\n  customer_memberships  CustomerPortalMembership[]\n  invitations_sent      Invitation[]               @relation(\"InvitationInviter\")\n  audit_events          AuditEvent[]               @relation(\"AuditActorUser\")\n\n  @@index([email])\n  @@index([phone])\n  @@index([status])\n  @@map(\"users\")\n}\n\nmodel PasswordResetToken {\n  id         String    @id @default(uuid())\n  token_hash String    @unique\n  user_uuid  String\n  expires_at DateTime\n  used_at    DateTime?\n  created_at DateTime  @default(now())\n\n  user User @relation(fields: [user_uuid], references: [id], onDelete: Cascade)\n\n  @@index([user_uuid])\n  @@index([expires_at])\n  @@map(\"password_reset_tokens\")\n}\n\n/// 01 §6, §74 — configured authentication factors per user (passkeys, OAuth links, MFA).\nmodel UserAuthMethod {\n  id           String         @id @default(uuid())\n  user_id      String\n  type         AuthMethodType\n  /// Provider or credential identifier: OAuth subject, passkey credential id, phone number, etc.\n  identifier   String?\n  /// Hashed secret where applicable (TOTP seed, recovery codes). Never plain text.\n  secret_hash  String?\n  label        String?\n  /// Provider-specific data (OAuth provider name, passkey public key, transports, …).\n  metadata     Json?\n  verified_at  DateTime?\n  last_used_at DateTime?\n  disabled_at  DateTime?\n  created_at   DateTime       @default(now())\n  updated_at   DateTime       @updatedAt\n\n  user User @relation(fields: [user_id], references: [id], onDelete: Cascade)\n\n  @@unique([user_id, type, identifier])\n  @@index([user_id])\n  @@map(\"user_auth_methods\")\n}\n\n/// 01 §72 — active sessions, revocable by the user or by security policy.\nmodel UserSession {\n  id                     String    @id @default(uuid())\n  user_id                String\n  /// Organization active in this session (01 §26). Null before the user picks one.\n  active_organization_id String?\n  /// 01 §27 — selected branch context; null means entire organization.\n  active_branch_id       String?\n  token_hash             String    @unique\n  device                 String?\n  browser                String?\n  ip_address             String?\n  location_approx        String?\n  user_agent             String?\n  last_activity_at       DateTime  @default(now())\n  expires_at             DateTime\n  revoked_at             DateTime?\n  revoked_reason         String?\n  created_at             DateTime  @default(now())\n\n  user User @relation(fields: [user_id], references: [id], onDelete: Cascade)\n\n  @@index([user_id])\n  @@index([expires_at])\n  @@map(\"user_sessions\")\n}\n\n/// 01 §127 — user-specific preferences. These are not permissions.\nmodel UserPreference {\n  user_id                  String   @id\n  theme                    String?\n  default_organization_id  String?\n  default_branch_id        String?\n  default_team_id          String?\n  /// Per-user notification defaults; the engine is docs/features/14 (LOG-403).\n  notification_preferences Json?\n  dashboard_layout         Json?\n  updated_at               DateTime @updatedAt\n\n  user User @relation(fields: [user_id], references: [id], onDelete: Cascade)\n\n  @@map(\"user_preferences\")\n}\n\n// =====================================================================\n// Organization (tenant) — 01 §8–15, §70, §73, §128\n// =====================================================================\n\n/// 01 §8 — the tenant. Every major resource belongs to exactly one Organization (01 §9).\nmodel Organization {\n  id              String             @id @default(uuid())\n  legal_name      String\n  display_name    String\n  short_name      String?\n  slug            String             @unique\n  logo_url        String?\n  website         String?\n  country         String?\n  contact_email   String?\n  contact_phone   String?\n  address         Json?\n  tax_identifiers Json?\n  status          OrganizationStatus @default(SETUP)\n\n  // 01 §14, §128 — organization defaults; branches and users may override.\n  default_currency String  @default(\"EUR\")\n  default_timezone String  @default(\"Europe/Athens\")\n  default_language String  @default(\"en\")\n  default_locale   String?\n  date_format      String?\n  number_format    String?\n  week_start       Int     @default(1)\n  working_days     Json?\n  business_hours   Json?\n\n  /// 01 §15 — consumed by every module instead of per-module branding.\n  branding Json?\n  /// Non-structured organization defaults (project defaults, document defaults, notification defaults).\n  settings Json?\n\n  /// 01 §103 — deletion lifecycle.\n  deletion_requested_at DateTime?\n  deletion_scheduled_at DateTime?\n  deleted_at            DateTime?\n  created_at            DateTime  @default(now())\n  updated_at            DateTime  @updatedAt\n\n  security_policy      OrganizationSecurityPolicy?\n  domains              OrganizationDomain[]\n  modules              OrganizationModule[]\n  branches             Branch[]\n  teams                Team[]\n  memberships          Membership[]\n  roles                Role[]\n  invitations          Invitation[]\n  sso_configurations   SsoConfiguration[]\n  service_accounts     ServiceAccount[]\n  api_keys             ApiKey[]\n  delegations          Delegation[]\n  customer_memberships CustomerPortalMembership[]\n  audit_events         AuditEvent[]\n\n  // 02 CRM\n  crm_companies            CrmCompany[]\n  crm_contacts             CrmContact[]\n  crm_leads                CrmLead[]\n  crm_deals                CrmDeal[]\n  crm_pipelines            CrmPipeline[]\n  crm_lead_sources         CrmLeadSource[]\n  crm_lead_statuses        CrmLeadStatus[]\n  crm_lifecycle_stages     CrmLifecycleStage[]\n  crm_activities           CrmActivity[]\n  crm_notes                CrmNote[]\n  crm_assignment_rules     CrmAssignmentRule[]\n  crm_import_jobs          CrmImportJob[]\n  // 03 Proposals\n  proposal_templates       ProposalTemplate[]\n  proposals                Proposal[]\n  number_sequences         NumberSequence[]\n  // 04 Contracts\n  contract_types           ContractType[]\n  contract_templates       ContractTemplate[]\n  contract_clauses         ContractClause[]\n  contract_approval_rules  ContractApprovalRule[]\n  contracts                Contract[]\n  signature_requests       SignatureRequest[]\n  // 05 Projects\n  project_types            ProjectType[]\n  project_statuses         ProjectStatus[]\n  project_templates        ProjectTemplate[]\n  projects                 Project[]\n  // 06 Tasks\n  task_statuses            TaskStatus[]\n  task_types               TaskType[]\n  task_labels              TaskLabel[]\n  tasks                    Task[]\n  cycles                   Cycle[]\n  releases                 Release[]\n  custom_field_groups      CustomFieldGroup[]\n  custom_field_definitions CustomFieldDefinition[]\n  tags                     Tag[]\n  saved_views              SavedView[]\n\n  @@index([status])\n  @@map(\"organizations\")\n}\n\n/// 01 §73–74 — organization security policy.\nmodel OrganizationSecurityPolicy {\n  organization_id                 String    @id\n  password_min_length             Int       @default(10)\n  password_require_symbols        Boolean   @default(false)\n  password_max_age_days           Int?\n  mfa_policy                      MfaPolicy @default(OPTIONAL)\n  sso_required                    Boolean   @default(false)\n  session_duration_minutes        Int       @default(43200)\n  idle_timeout_minutes            Int?\n  allowed_email_domains           String[]  @default([])\n  /// Invitations limited to allowed domains.\n  restrict_invitations_to_domains Boolean   @default(false)\n  allowed_ip_ranges               String[]  @default([])\n  /// Portal users may use the same policy or a lighter one (01 §79).\n  portal_mfa_policy               MfaPolicy @default(OPTIONAL)\n  updated_at                      DateTime  @updatedAt\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n\n  @@map(\"organization_security_policies\")\n}\n\n/// 01 §70 — verified corporate email domains.\nmodel OrganizationDomain {\n  id                 String                   @id @default(uuid())\n  organization_id    String\n  domain             String\n  status             DomainVerificationStatus @default(PENDING)\n  verification_token String\n  verified_at        DateTime?\n  /// Allow users with this email domain to discover and request to join (01 §70).\n  allow_discovery    Boolean                  @default(false)\n  /// Automatically provision membership on SSO login from this domain.\n  auto_provision     Boolean                  @default(false)\n  created_at         DateTime                 @default(now())\n  updated_at         DateTime                 @updatedAt\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n\n  @@unique([domain])\n  @@index([organization_id])\n  @@map(\"organization_domains\")\n}\n\n/// 01 §56 — which products are enabled for the organization.\nmodel OrganizationModule {\n  id              String    @id @default(uuid())\n  organization_id String\n  module          ModuleKey\n  enabled         Boolean   @default(true)\n  enabled_at      DateTime?\n  disabled_at     DateTime?\n  settings        Json?\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n\n  @@unique([organization_id, module])\n  @@map(\"organization_modules\")\n}\n\n// =====================================================================\n// Branches — 01 §16–23, §120–122\n// =====================================================================\n\n/// 01 §18 — an organizational unit inside an Organization. Never a tenant.\nmodel Branch {\n  id               String       @id @default(uuid())\n  organization_id  String\n  parent_branch_id String?\n  name             String\n  code             String?\n  kind             BranchKind   @default(OPERATIONAL)\n  status           BranchStatus @default(ACTIVE)\n  country          String?\n  region           String?\n  city             String?\n  address          Json?\n  phone            String?\n  email            String?\n  /// Materialized path of ancestor ids for hierarchy queries (01 §17, §52).\n  path             String       @default(\"\")\n  depth            Int          @default(0)\n  /// Cost center / currency references consumed by Finance (01 §34).\n  cost_center_code String?\n  currency         String?\n\n  // 01 §120–121 — overrides; organization defaults remain the fallback.\n  timezone       String?\n  locale         String?\n  language       String?\n  date_format    String?\n  week_start     Int?\n  working_days   Json?\n  business_hours Json?\n  /// 01 §120 branch-level branding override (optional).\n  branding       Json?\n  custom_fields  Json?\n\n  archived_at DateTime?\n  created_at  DateTime  @default(now())\n  updated_at  DateTime  @updatedAt\n\n  organization         Organization       @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  parent               Branch?            @relation(\"BranchHierarchy\", fields: [parent_branch_id], references: [id], onDelete: Restrict)\n  children             Branch[]           @relation(\"BranchHierarchy\")\n  managers             BranchManager[]\n  holidays             BranchHoliday[]\n  memberships          MembershipBranch[]\n  teams                Team[]\n  invitations          Invitation[]\n  group_mappings       SsoGroupMapping[]\n  crm_company_branches CrmCompanyBranch[]\n  crm_leads            CrmLead[]\n  crm_deals            CrmDeal[]\n  proposals            Proposal[]\n  contracts            Contract[]\n  projects             Project[]\n  project_branches     ProjectBranch[]\n\n  @@unique([organization_id, code])\n  @@index([organization_id])\n  @@index([parent_branch_id])\n  @@index([organization_id, status])\n  @@map(\"branches\")\n}\n\n/// 01 §20 — responsible Members for a branch.\nmodel BranchManager {\n  id            String   @id @default(uuid())\n  branch_id     String\n  membership_id String\n  title         String?\n  created_at    DateTime @default(now())\n\n  branch     Branch     @relation(fields: [branch_id], references: [id], onDelete: Cascade)\n  membership Membership @relation(fields: [membership_id], references: [id], onDelete: Cascade)\n\n  @@unique([branch_id, membership_id])\n  @@map(\"branch_managers\")\n}\n\n/// 01 §122 — local holiday calendars consumed by Calendar (19) and Employees (10).\nmodel BranchHoliday {\n  id         String   @id @default(uuid())\n  branch_id  String\n  name       String\n  date       DateTime @db.Date\n  recurring  Boolean  @default(false)\n  created_at DateTime @default(now())\n\n  branch Branch @relation(fields: [branch_id], references: [id], onDelete: Cascade)\n\n  @@unique([branch_id, date, name])\n  @@index([branch_id, date])\n  @@map(\"branch_holidays\")\n}\n\n// =====================================================================\n// Teams — 01 §40–43, §87–88\n// =====================================================================\n\n/// 01 §40 — functional collaboration group. Not a Branch.\nmodel Team {\n  id              String    @id @default(uuid())\n  organization_id String\n  parent_team_id  String?\n  /// 01 §88 — set when the team is restricted to one branch; null for organization-wide / cross-branch.\n  branch_id       String?\n  name            String\n  slug            String?\n  description     String?\n  kind            TeamKind  @default(TEAM)\n  archived_at     DateTime?\n  created_at      DateTime  @default(now())\n  updated_at      DateTime  @updatedAt\n\n  organization        Organization        @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  parent              Team?               @relation(\"TeamHierarchy\", fields: [parent_team_id], references: [id], onDelete: SetNull)\n  children            Team[]              @relation(\"TeamHierarchy\")\n  branch              Branch?             @relation(fields: [branch_id], references: [id], onDelete: SetNull)\n  members             TeamMembership[]\n  invitations         Invitation[]\n  group_mappings      SsoGroupMapping[]\n  crm_companies       CrmCompany[]\n  crm_deals           CrmDeal[]\n  crm_pipelines       CrmPipeline[]\n  saved_views         SavedView[]\n  projects            Project[]\n  project_allocations ProjectAllocation[]\n  tasks               Task[]\n  task_statuses       TaskStatus[]\n  cycles              Cycle[]\n  releases            Release[]\n\n  @@unique([organization_id, slug])\n  @@index([organization_id])\n  @@index([parent_team_id])\n  @@index([branch_id])\n  @@map(\"teams\")\n}\n\n/// 01 §42\nmodel TeamMembership {\n  id            String    @id @default(uuid())\n  team_id       String\n  membership_id String\n  /// Free-form team role label (lead, member, …). Permissions come from Role assignments scoped to the team.\n  team_role     String?\n  is_primary    Boolean   @default(false)\n  started_at    DateTime  @default(now())\n  ended_at      DateTime?\n  created_at    DateTime  @default(now())\n\n  team       Team       @relation(fields: [team_id], references: [id], onDelete: Cascade)\n  membership Membership @relation(fields: [membership_id], references: [id], onDelete: Cascade)\n\n  @@unique([team_id, membership_id])\n  @@index([membership_id])\n  @@map(\"team_memberships\")\n}\n\n// =====================================================================\n// Membership — 01 §7, §21, §24–25, §77–78, §89–90, §125–126, §131\n// =====================================================================\n\n/// 01 §24 — the authorization relationship between a User and an Organization.\n/// Employee data (10) is NOT here; see 01 §80–81.\nmodel Membership {\n  id                  String             @id @default(uuid())\n  user_id             String\n  organization_id     String\n  type                MembershipType     @default(INTERNAL)\n  status              MembershipStatus   @default(ACTIVE)\n  provisioning_source ProvisioningSource @default(MANUAL)\n  /// SCIM / IdP external identifier (01 §68).\n  external_id         String?\n  invited_by_user_id  String?\n  /// 01 §125–126 — defaults for navigation and creation; never restrict permissions.\n  default_branch_id   String?\n  default_team_id     String?\n  job_title           String?\n  joined_at           DateTime           @default(now())\n  last_active_at      DateTime?\n  suspended_at        DateTime?\n  deactivated_at      DateTime?\n  /// 01 §131 — offboarding record (who, when, ownership transfers performed).\n  offboarding         Json?\n  created_at          DateTime           @default(now())\n  updated_at          DateTime           @updatedAt\n\n  user         User         @relation(fields: [user_id], references: [id], onDelete: Cascade)\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n\n  branches               MembershipBranch[]\n  teams                  TeamMembership[]\n  managed_branches       BranchManager[]\n  module_access          MembershipModuleAccess[]\n  role_assignments       RoleAssignment[]\n  permission_grants      PermissionGrant[]\n  api_keys               ApiKey[]\n  delegations_given      Delegation[]             @relation(\"DelegationDelegator\")\n  delegations_received   Delegation[]             @relation(\"DelegationDelegate\")\n  owned_service_accounts ServiceAccount[]\n\n  // 02 CRM ownership (02 §20)\n  owned_companies         CrmCompany[]        @relation(\"CrmCompanyOwner\")\n  managed_companies       CrmCompany[]        @relation(\"CrmCompanyAccountManager\")\n  success_owned_companies CrmCompany[]        @relation(\"CrmCompanySuccessOwner\")\n  owned_contacts          CrmContact[]        @relation(\"CrmContactOwner\")\n  owned_leads             CrmLead[]           @relation(\"CrmLeadOwner\")\n  owned_deals             CrmDeal[]           @relation(\"CrmDealOwner\")\n  owned_activities        CrmActivity[]       @relation(\"CrmActivityOwner\")\n  authored_notes          CrmNote[]           @relation(\"CrmNoteAuthor\")\n  // 03 Proposals\n  owned_proposals         Proposal[]          @relation(\"ProposalOwner\")\n  proposal_approvals      ProposalApproval[]  @relation(\"ProposalApprover\")\n  proposal_comments       ProposalComment[]   @relation(\"ProposalCommentAuthor\")\n  // 04 Contracts\n  owned_contracts         Contract[]          @relation(\"ContractOwner\")\n  contract_reviews        ContractReview[]    @relation(\"ContractReviewer\")\n  contract_approvals      ContractApproval[]  @relation(\"ContractApprover\")\n  contract_comments       ContractComment[]   @relation(\"ContractCommentAuthor\")\n  contract_signatories    ContractSignatory[]\n  // 05 Projects\n  owned_projects          Project[]           @relation(\"ProjectOwner\")\n  project_memberships     ProjectMember[]\n  project_allocations     ProjectAllocation[]\n  project_gate_approvals  ProjectGate[]       @relation(\"ProjectGateApprover\")\n  // 06 Tasks\n  assigned_tasks          Task[]              @relation(\"TaskAssignee\")\n  reported_tasks          Task[]              @relation(\"TaskReporter\")\n  task_assignments        TaskAssignee[]\n  task_comments           TaskComment[]       @relation(\"TaskCommentAuthor\")\n  task_watches            TaskWatcher[]\n  saved_views             SavedView[]\n  crm_import_jobs         CrmImportJob[]\n\n  @@unique([user_id, organization_id])\n  @@unique([organization_id, external_id])\n  @@index([organization_id, status])\n  @@index([user_id])\n  @@map(\"memberships\")\n}\n\n/// 01 §21, §90 — a Member can belong to one or many branches.\nmodel MembershipBranch {\n  id               String    @id @default(uuid())\n  membership_id    String\n  branch_id        String\n  is_primary       Boolean   @default(false)\n  /// 01 §91 — whether access cascades to child branches.\n  include_children Boolean   @default(false)\n  started_at       DateTime  @default(now())\n  ended_at         DateTime?\n\n  membership Membership @relation(fields: [membership_id], references: [id], onDelete: Cascade)\n  branch     Branch     @relation(fields: [branch_id], references: [id], onDelete: Cascade)\n\n  @@unique([membership_id, branch_id])\n  @@index([branch_id])\n  @@map(\"membership_branches\")\n}\n\n/// 01 §56–57 — per-member product access, evaluated before feature permissions.\nmodel MembershipModuleAccess {\n  id                 String    @id @default(uuid())\n  membership_id      String\n  module             ModuleKey\n  enabled            Boolean   @default(true)\n  granted_by_user_id String?\n  created_at         DateTime  @default(now())\n  updated_at         DateTime  @updatedAt\n\n  membership Membership @relation(fields: [membership_id], references: [id], onDelete: Cascade)\n\n  @@unique([membership_id, module])\n  @@map(\"membership_module_access\")\n}\n\n// =====================================================================\n// Roles & Permissions — 01 §44–63, §92–97, §111–114\n// =====================================================================\n\n/// 01 §46 — the global permission catalog. Keys follow `<module>.<resource>.<action>`.\nmodel Permission {\n  id             String    @id @default(uuid())\n  key            String    @unique\n  module         ModuleKey\n  resource       String\n  action         String\n  description    String?\n  /// 01 §59 — requires elevated roles; surfaced in conflict warnings (01 §97).\n  is_sensitive   Boolean   @default(false)\n  /// 01 §60 — field-level permission marker.\n  is_field_level Boolean   @default(false)\n  created_at     DateTime  @default(now())\n\n  roles  RolePermission[]\n  grants PermissionGrant[]\n\n  @@index([module])\n  @@map(\"permissions\")\n}\n\n/// 01 §44–45, §111 — reusable permission bundle. organization_id is null for system roles and\n/// platform-provided templates (01 §111) that organizations clone.\nmodel Role {\n  id               String      @id @default(uuid())\n  organization_id  String?\n  name             String\n  slug             String\n  description      String?\n  type             RoleType    @default(ORGANIZATION)\n  status           RoleStatus  @default(PUBLISHED)\n  is_system        Boolean     @default(false)\n  /// Template this role was cloned from (01 §111).\n  template_role_id String?\n  /// Default scope type this role is intended for (01 §50).\n  default_scope    ScopeType   @default(ORGANIZATION)\n  /// Modules this role grants product access to when assigned (01 §109).\n  modules          ModuleKey[] @default([])\n  created_at       DateTime    @default(now())\n  updated_at       DateTime    @updatedAt\n\n  organization         Organization?              @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  permissions          RolePermission[]\n  assignments          RoleAssignment[]\n  invitations          Invitation[]\n  group_mappings       SsoGroupMapping[]\n  customer_memberships CustomerPortalMembership[]\n  project_members      ProjectMember[]\n\n  @@unique([organization_id, slug])\n  @@index([organization_id, type])\n  @@map(\"roles\")\n}\n\n/// 01 §44, §53 — permissions bundled in a role, with optional explicit deny.\nmodel RolePermission {\n  role_id       String\n  permission_id String\n  effect        PermissionEffect @default(ALLOW)\n  /// Optional field-level or resource-level restriction data (01 §48, §60).\n  conditions    Json?\n\n  role       Role       @relation(fields: [role_id], references: [id], onDelete: Cascade)\n  permission Permission @relation(fields: [permission_id], references: [id], onDelete: Cascade)\n\n  @@id([role_id, permission_id])\n  @@index([permission_id])\n  @@map(\"role_permissions\")\n}\n\n/// 01 §92–93 — a role given to a principal (Member or Service Account) within a scope.\n/// scope_id references the Branch, Team, Project (05), Customer (02) or resource identified by scope_type.\nmodel RoleAssignment {\n  id                 String    @id @default(uuid())\n  membership_id      String?\n  service_account_id String?\n  role_id            String\n  scope_type         ScopeType @default(ORGANIZATION)\n  scope_id           String?\n  granted_by_user_id String?\n  reason             String?\n  valid_from         DateTime  @default(now())\n  /// 01 §93 — temporary access; null means permanent.\n  valid_until        DateTime?\n  revoked_at         DateTime?\n  created_at         DateTime  @default(now())\n\n  membership      Membership?     @relation(fields: [membership_id], references: [id], onDelete: Cascade)\n  service_account ServiceAccount? @relation(fields: [service_account_id], references: [id], onDelete: Cascade)\n  role            Role            @relation(fields: [role_id], references: [id], onDelete: Cascade)\n\n  @@index([membership_id])\n  @@index([service_account_id])\n  @@index([role_id])\n  @@index([scope_type, scope_id])\n  @@map(\"role_assignments\")\n}\n\n/// 01 §49, §53 — explicit per-member allow or deny for one permission, outside any role.\nmodel PermissionGrant {\n  id                 String           @id @default(uuid())\n  membership_id      String\n  permission_id      String\n  effect             PermissionEffect @default(ALLOW)\n  scope_type         ScopeType        @default(ORGANIZATION)\n  scope_id           String?\n  granted_by_user_id String?\n  reason             String?\n  valid_from         DateTime         @default(now())\n  valid_until        DateTime?\n  revoked_at         DateTime?\n  created_at         DateTime         @default(now())\n\n  membership Membership @relation(fields: [membership_id], references: [id], onDelete: Cascade)\n  permission Permission @relation(fields: [permission_id], references: [id], onDelete: Cascade)\n\n  @@index([membership_id])\n  @@index([permission_id])\n  @@index([scope_type, scope_id])\n  @@map(\"permission_grants\")\n}\n\n/// 01 §94 — temporary delegation of selected responsibilities.\nmodel Delegation {\n  id                      String           @id @default(uuid())\n  organization_id         String\n  delegator_membership_id String\n  delegate_membership_id  String\n  /// Permission keys or role ids delegated.\n  permission_keys         String[]         @default([])\n  role_ids                String[]         @default([])\n  scope_type              ScopeType        @default(ORGANIZATION)\n  scope_id                String?\n  status                  DelegationStatus @default(SCHEDULED)\n  reason                  String?\n  starts_at               DateTime\n  ends_at                 DateTime\n  revoked_at              DateTime?\n  created_at              DateTime         @default(now())\n  updated_at              DateTime         @updatedAt\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  delegator    Membership   @relation(\"DelegationDelegator\", fields: [delegator_membership_id], references: [id], onDelete: Cascade)\n  delegate     Membership   @relation(\"DelegationDelegate\", fields: [delegate_membership_id], references: [id], onDelete: Cascade)\n\n  @@index([organization_id, status])\n  @@index([delegate_membership_id])\n  @@map(\"delegations\")\n}\n\n// =====================================================================\n// Invitations — 01 §65–66\n// =====================================================================\n\nmodel Invitation {\n  id                 String             @id @default(uuid())\n  organization_id    String\n  email              String\n  type               MembershipType     @default(INTERNAL)\n  branch_id          String?\n  team_id            String?\n  role_id            String?\n  /// Modules to enable on acceptance (01 §65).\n  modules            ModuleKey[]        @default([])\n  token_hash         String             @unique\n  status             InvitationStatus   @default(PENDING)\n  source             ProvisioningSource @default(MANUAL)\n  message            String?\n  invited_by_user_id String?\n  expires_at         DateTime\n  accepted_at        DateTime?\n  /// Membership created on acceptance.\n  membership_id      String?\n  cancelled_at       DateTime?\n  rejected_at        DateTime?\n  created_at         DateTime           @default(now())\n  updated_at         DateTime           @updatedAt\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  branch       Branch?      @relation(fields: [branch_id], references: [id], onDelete: SetNull)\n  team         Team?        @relation(fields: [team_id], references: [id], onDelete: SetNull)\n  role         Role?        @relation(fields: [role_id], references: [id], onDelete: SetNull)\n  invited_by   User?        @relation(\"InvitationInviter\", fields: [invited_by_user_id], references: [id], onDelete: SetNull)\n\n  @@index([organization_id, status])\n  @@index([email])\n  @@index([expires_at])\n  @@map(\"invitations\")\n}\n\n// =====================================================================\n// SSO & provisioning — 01 §68–71\n// =====================================================================\n\n/// 01 §69 — identity provider configuration per organization.\nmodel SsoConfiguration {\n  id              String      @id @default(uuid())\n  organization_id String\n  name            String\n  protocol        SsoProtocol\n  enabled         Boolean     @default(false)\n  /// Issuer, entity id, metadata URL, client id, certificates, attribute mapping. Secrets are stored encrypted.\n  config          Json\n  auto_provision  Boolean     @default(false)\n  /// 01 §67–68 — SCIM provisioning token hash and settings, when enabled.\n  scim_enabled    Boolean     @default(false)\n  scim_token_hash String?\n  created_at      DateTime    @default(now())\n  updated_at      DateTime    @updatedAt\n\n  organization   Organization      @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  group_mappings SsoGroupMapping[]\n\n  @@index([organization_id])\n  @@map(\"sso_configurations\")\n}\n\n/// 01 §71 — external IdP group → role / team / branch / module access.\nmodel SsoGroupMapping {\n  id                   String      @id @default(uuid())\n  sso_configuration_id String\n  external_group       String\n  role_id              String?\n  team_id              String?\n  branch_id            String?\n  modules              ModuleKey[] @default([])\n  created_at           DateTime    @default(now())\n\n  sso_configuration SsoConfiguration @relation(fields: [sso_configuration_id], references: [id], onDelete: Cascade)\n  role              Role?            @relation(fields: [role_id], references: [id], onDelete: SetNull)\n  team              Team?            @relation(fields: [team_id], references: [id], onDelete: SetNull)\n  branch            Branch?          @relation(fields: [branch_id], references: [id], onDelete: SetNull)\n\n  @@unique([sso_configuration_id, external_group])\n  @@map(\"sso_group_mappings\")\n}\n\n// =====================================================================\n// API access & service accounts — 01 §75–76\n// =====================================================================\n\n/// 01 §76 — non-human identity for automation. Permissions come from RoleAssignment.\nmodel ServiceAccount {\n  id                  String               @id @default(uuid())\n  organization_id     String\n  owner_membership_id String?\n  name                String\n  purpose             String?\n  status              ServiceAccountStatus @default(ACTIVE)\n  expires_at          DateTime?\n  created_at          DateTime             @default(now())\n  updated_at          DateTime             @updatedAt\n\n  organization     Organization     @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  owner            Membership?      @relation(fields: [owner_membership_id], references: [id], onDelete: SetNull)\n  role_assignments RoleAssignment[]\n  api_keys         ApiKey[]\n\n  @@unique([organization_id, name])\n  @@index([organization_id, status])\n  @@map(\"service_accounts\")\n}\n\n/// 01 §75 — API credential owned by a Member or a Service Account. Never inherits unlimited permissions.\nmodel ApiKey {\n  id                 String    @id @default(uuid())\n  organization_id    String\n  membership_id      String?\n  service_account_id String?\n  name               String\n  /// First characters shown to the user for identification.\n  key_prefix         String\n  key_hash           String    @unique\n  /// Optional narrowing of the owner's permissions (permission keys).\n  scopes             String[]  @default([])\n  expires_at         DateTime?\n  last_used_at       DateTime?\n  rotated_from_id    String?\n  revoked_at         DateTime?\n  created_at         DateTime  @default(now())\n\n  organization    Organization    @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  membership      Membership?     @relation(fields: [membership_id], references: [id], onDelete: Cascade)\n  service_account ServiceAccount? @relation(fields: [service_account_id], references: [id], onDelete: Cascade)\n\n  @@index([organization_id])\n  @@index([membership_id])\n  @@index([service_account_id])\n  @@map(\"api_keys\")\n}\n\n// =====================================================================\n// Customer Portal identity — 01 §79\n// =====================================================================\n\n/// 01 §79 — a User's membership to a Customer (a CRM Company owned by docs/features/02, LOG-404)\n/// inside an agency Organization. customer_id has no relation until the CRM module defines companies.\nmodel CustomerPortalMembership {\n  id                 String           @id @default(uuid())\n  organization_id    String\n  /// CRM Company id (02). No FK until LOG-404 is implemented.\n  customer_id        String\n  user_id            String\n  /// Role of type CUSTOMER_PORTAL (01 §79 defaults: Owner, Administrator, Manager, Finance, Legal, Viewer).\n  role_id            String?\n  status             MembershipStatus @default(ACTIVE)\n  invited_by_user_id String?\n  joined_at          DateTime         @default(now())\n  last_active_at     DateTime?\n  deactivated_at     DateTime?\n  created_at         DateTime         @default(now())\n  updated_at         DateTime         @updatedAt\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  user         User         @relation(fields: [user_id], references: [id], onDelete: Cascade)\n  role         Role?        @relation(fields: [role_id], references: [id], onDelete: SetNull)\n\n  @@unique([organization_id, customer_id, user_id])\n  @@index([customer_id])\n  @@index([user_id])\n  @@map(\"customer_portal_memberships\")\n}\n\n// =====================================================================\n// Audit — 01 §99–100, §139\n// =====================================================================\n\n/// Immutable audit event. Identity and access changes are written here by module 01;\n/// other modules append their own event types using the same table.\nmodel AuditEvent {\n  id                       String         @id @default(uuid())\n  organization_id          String?\n  actor_type               AuditActorType @default(USER)\n  actor_user_id            String?\n  actor_service_account_id String?\n  /// Stable key, e.g. `membership.role_assigned`, `user.login`, `sso.configuration_changed`.\n  event_type               String\n  resource_type            String?\n  resource_id              String?\n  /// Before/after values or event-specific payload.\n  metadata                 Json?\n  ip_address               String?\n  user_agent               String?\n  created_at               DateTime       @default(now())\n\n  organization Organization? @relation(fields: [organization_id], references: [id], onDelete: SetNull)\n  actor_user   User?         @relation(\"AuditActorUser\", fields: [actor_user_id], references: [id], onDelete: SetNull)\n\n  @@index([organization_id, created_at])\n  @@index([actor_user_id, created_at])\n  @@index([event_type])\n  @@index([resource_type, resource_id])\n  @@map(\"audit_events\")\n}\n\n// =====================================================================\n// Legacy — owned by docs/features/17-documents-file-management.md (LOG-407).\n// Kept as-is until module 17 is implemented; it will gain organization_id and scope then.\n// =====================================================================\n\nmodel Document {\n  id         String       @id @default(uuid())\n  user_uuid  String\n  filename   String\n  mimetype   String\n  size       Int\n  url        String\n  path       String\n  type       DocumentType @default(LOGO)\n  created_at DateTime     @default(now())\n\n  @@index([user_uuid])\n  @@map(\"documents\")\n}\n\n// =====================================================================\n// Platform shared concepts defined by 02 CRM — custom fields (§24–26),\n// tags (§36), saved views (§29). Consumed by every module.\n// =====================================================================\n\n/// Entities that can carry custom fields, tags and saved views. Modules append their own values.\nenum RecordEntityType {\n  CRM_COMPANY\n  CRM_CONTACT\n  CRM_LEAD\n  CRM_DEAL\n  CRM_ACTIVITY\n  PROJECT\n  TASK\n  CONTRACT\n  PROPOSAL\n  TICKET\n  DOCUMENT\n  FINANCIAL_RECORD\n  EMPLOYEE\n  INVOICE\n}\n\n/// 02 §24 — supported field types.\nenum CustomFieldType {\n  TEXT\n  LONG_TEXT\n  NUMBER\n  DECIMAL\n  CURRENCY\n  PERCENTAGE\n  BOOLEAN\n  DATE\n  DATETIME\n  EMAIL\n  PHONE\n  URL\n  DROPDOWN\n  MULTI_SELECT\n  RADIO\n  USER\n  TEAM\n  COMPANY\n  CONTACT\n  DEAL\n  RECORD_REFERENCE\n}\n\nenum SavedViewVisibility {\n  PERSONAL\n  TEAM\n  ORGANIZATION\n}\n\n/// 02 §25 — logical sections for shared fields.\nmodel CustomFieldGroup {\n  id              String   @id @default(uuid())\n  organization_id String\n  name            String\n  description     String?\n  sort_order      Int      @default(0)\n  created_at      DateTime @default(now())\n\n  organization Organization            @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  fields       CustomFieldDefinition[]\n\n  @@unique([organization_id, name])\n  @@map(\"custom_field_groups\")\n}\n\n/// 02 §24–26 — one definition; shared fields list several entity types (02 §25).\n/// `key` is the stable API identifier (02 §26); `label` may change.\nmodel CustomFieldDefinition {\n  id              String             @id @default(uuid())\n  organization_id String\n  group_id        String?\n  key             String\n  label           String\n  description     String?\n  type            CustomFieldType\n  /// Entity types this field applies to. Length > 1 means a shared field (02 §25).\n  entity_types    RecordEntityType[]\n  is_shared       Boolean            @default(false)\n  is_required     Boolean            @default(false)\n  /// Options for DROPDOWN / MULTI_SELECT / RADIO: [{ value, label, color?, sort_order? }]\n  options         Json?\n  default_value   Json?\n  /// Validation rules (min, max, regex, length …).\n  validation      Json?\n  /// Role-based visibility and visibility rules (02 §24).\n  visibility      Json?\n  is_searchable   Boolean            @default(true)\n  is_filterable   Boolean            @default(true)\n  is_sortable     Boolean            @default(false)\n  sort_order      Int                @default(0)\n  archived_at     DateTime?\n  created_at      DateTime           @default(now())\n  updated_at      DateTime           @updatedAt\n\n  organization Organization       @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  group        CustomFieldGroup?  @relation(fields: [group_id], references: [id], onDelete: SetNull)\n  values       CustomFieldValue[]\n\n  @@unique([organization_id, key])\n  @@index([organization_id])\n  @@map(\"custom_field_definitions\")\n}\n\n/// Value of a custom field on a record. entity_id points at the table named by entity_type.\nmodel CustomFieldValue {\n  id            String           @id @default(uuid())\n  definition_id String\n  entity_type   RecordEntityType\n  entity_id     String\n  /// Typed value stored as JSON (string, number, boolean, ISO date, option value, option values[], referenced id).\n  value         Json?\n  /// Denormalized text for search/filter.\n  value_text    String?\n  updated_at    DateTime         @updatedAt\n\n  definition CustomFieldDefinition @relation(fields: [definition_id], references: [id], onDelete: Cascade)\n\n  @@unique([definition_id, entity_id])\n  @@index([entity_type, entity_id])\n  @@index([definition_id, value_text])\n  @@map(\"custom_field_values\")\n}\n\n/// Organization-scoped tags, applied to any record through Tagging.\nmodel Tag {\n  id              String             @id @default(uuid())\n  organization_id String\n  name            String\n  slug            String\n  color           String?\n  /// Restrict a tag to certain entity types; empty = any.\n  entity_types    RecordEntityType[] @default([])\n  created_at      DateTime           @default(now())\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  taggings     Tagging[]\n\n  @@unique([organization_id, slug])\n  @@map(\"tags\")\n}\n\nmodel Tagging {\n  tag_id      String\n  entity_type RecordEntityType\n  entity_id   String\n  created_at  DateTime         @default(now())\n\n  tag Tag @relation(fields: [tag_id], references: [id], onDelete: Cascade)\n\n  @@id([tag_id, entity_type, entity_id])\n  @@index([entity_type, entity_id])\n  @@map(\"taggings\")\n}\n\n/// 02 §29 — saved views with filters, sorting, grouping, columns; personal, team or organization-wide.\nmodel SavedView {\n  id                  String              @id @default(uuid())\n  organization_id     String\n  entity_type         RecordEntityType\n  name                String\n  /// table | kanban | pipeline | list | timeline | calendar | activity | forecast\n  layout              String              @default(\"table\")\n  visibility          SavedViewVisibility @default(PERSONAL)\n  owner_membership_id String?\n  team_id             String?\n  filters             Json?\n  sorting             Json?\n  grouping            Json?\n  columns             Json?\n  search              String?\n  is_default          Boolean             @default(false)\n  created_at          DateTime            @default(now())\n  updated_at          DateTime            @updatedAt\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  owner        Membership?  @relation(fields: [owner_membership_id], references: [id], onDelete: Cascade)\n  team         Team?        @relation(fields: [team_id], references: [id], onDelete: Cascade)\n\n  @@index([organization_id, entity_type])\n  @@index([owner_membership_id])\n  @@map(\"saved_views\")\n}\n\n// =====================================================================\n// 02 CRM & Sales Management — docs/features/02-crm-sales-management.md (LOG-404)\n// Owns: Company, Contact, Lead, Deal, Pipeline, Activities, Notes, lifecycle, ownership.\n// Does not own: Tasks (06), Proposals (03), Contracts (04), Projects (05), Tickets (13),\n// Invoices/Payments/Subscriptions (08), Calendar events (19). Those are referenced by id only.\n// Record history (02 §34) is written to audit_events (01 §139).\n// =====================================================================\n\n/// 02 §2 — company type; lifecycle stage is a separate, configurable dimension (02 §17).\nenum CrmCompanyType {\n  PROSPECT\n  CUSTOMER\n  PARTNER\n  VENDOR\n  OTHER\n}\n\n/// 02 §3 — contact roles within a company; a contact may hold several.\nenum CrmContactRole {\n  PRIMARY\n  DECISION_MAKER\n  TECHNICAL\n  BILLING\n  PROJECT_STAKEHOLDER\n  EXECUTIVE\n}\n\n/// 02 §13 — activity types. MEETING activities link to a Calendar event (19).\nenum CrmActivityType {\n  CALL\n  MEETING\n  FOLLOW_UP\n  REMINDER\n  APPOINTMENT\n  INTERNAL_COMMENT\n  EMAIL\n  OTHER\n}\n\nenum CrmActivityStatus {\n  PLANNED\n  COMPLETED\n  CANCELLED\n  NO_SHOW\n}\n\nenum CrmPriority {\n  LOW\n  NORMAL\n  HIGH\n  URGENT\n}\n\n/// 02 §11 — forecast categories.\nenum CrmForecastCategory {\n  PIPELINE\n  BEST_CASE\n  COMMIT\n  CLOSED_WON\n  CLOSED_LOST\n}\n\nenum CrmDealStatus {\n  OPEN\n  WON\n  LOST\n  ABANDONED\n}\n\n/// 02 §22 — import lifecycle.\nenum CrmImportStatus {\n  PENDING\n  VALIDATING\n  PREVIEW\n  IMPORTING\n  COMPLETED\n  FAILED\n  ROLLED_BACK\n}\n\n/// 01 §31 — how a branch relates to a company (one company, many branch relationships).\nenum CrmBranchRelationType {\n  OWNER\n  SALES\n  DELIVERY\n  SUPPORT\n  BILLING\n  OTHER\n}\n\n// --- Configuration -----------------------------------------------------------\n\n/// 02 §5 — configurable lead sources.\nmodel CrmLeadSource {\n  id              String    @id @default(uuid())\n  organization_id String\n  name            String\n  slug            String\n  is_default      Boolean   @default(false)\n  sort_order      Int       @default(0)\n  archived_at     DateTime?\n  created_at      DateTime  @default(now())\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  companies    CrmCompany[]\n  contacts     CrmContact[]\n  leads        CrmLead[]\n  deals        CrmDeal[]\n\n  @@unique([organization_id, slug])\n  @@map(\"crm_lead_sources\")\n}\n\n/// 02 §4 — configurable lead statuses.\nmodel CrmLeadStatus {\n  id              String    @id @default(uuid())\n  organization_id String\n  name            String\n  slug            String\n  color           String?\n  sort_order      Int       @default(0)\n  is_default      Boolean   @default(false)\n  is_converted    Boolean   @default(false)\n  is_lost         Boolean   @default(false)\n  archived_at     DateTime?\n  created_at      DateTime  @default(now())\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  leads        CrmLead[]\n\n  @@unique([organization_id, slug])\n  @@map(\"crm_lead_statuses\")\n}\n\n/// 02 §17 — configurable lifecycle stages (Lead → MQL → SQL → Opportunity → Customer → …).\nmodel CrmLifecycleStage {\n  id              String    @id @default(uuid())\n  organization_id String\n  name            String\n  slug            String\n  sort_order      Int       @default(0)\n  /// Reaching this stage marks the company as a Customer (terminology, Product_Specification §5a).\n  is_customer     Boolean   @default(false)\n  is_default      Boolean   @default(false)\n  archived_at     DateTime?\n  created_at      DateTime  @default(now())\n\n  organization Organization          @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  companies    CrmCompany[]\n  contacts     CrmContact[]\n  history      CrmLifecycleHistory[]\n\n  @@unique([organization_id, slug])\n  @@map(\"crm_lifecycle_stages\")\n}\n\n/// 02 §17 — historical lifecycle changes.\nmodel CrmLifecycleHistory {\n  id                 String   @id @default(uuid())\n  company_id         String?\n  contact_id         String?\n  stage_id           String\n  changed_by_user_id String?\n  changed_at         DateTime @default(now())\n\n  company CrmCompany?       @relation(fields: [company_id], references: [id], onDelete: Cascade)\n  contact CrmContact?       @relation(fields: [contact_id], references: [id], onDelete: Cascade)\n  stage   CrmLifecycleStage @relation(fields: [stage_id], references: [id], onDelete: Cascade)\n\n  @@index([company_id, changed_at])\n  @@index([contact_id, changed_at])\n  @@map(\"crm_lifecycle_history\")\n}\n\n/// 02 §8 — multiple pipelines per organization.\nmodel CrmPipeline {\n  id              String    @id @default(uuid())\n  organization_id String\n  name            String\n  slug            String\n  description     String?\n  /// Optional owning team (02 §21).\n  team_id         String?\n  is_default      Boolean   @default(false)\n  currency        String?\n  archived_at     DateTime?\n  created_at      DateTime  @default(now())\n  updated_at      DateTime  @updatedAt\n\n  organization Organization       @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  team         Team?              @relation(fields: [team_id], references: [id], onDelete: SetNull)\n  stages       CrmPipelineStage[]\n  deals        CrmDeal[]\n\n  @@unique([organization_id, slug])\n  @@map(\"crm_pipelines\")\n}\n\n/// 02 §8 — pipeline-specific stages with default probability.\nmodel CrmPipelineStage {\n  id                String              @id @default(uuid())\n  pipeline_id       String\n  name              String\n  slug              String\n  sort_order        Int                 @default(0)\n  /// Default win probability (0–100) applied to deals entering this stage.\n  probability       Int                 @default(0)\n  forecast_category CrmForecastCategory @default(PIPELINE)\n  is_won            Boolean             @default(false)\n  is_lost           Boolean             @default(false)\n  /// Days after which a deal in this stage is considered stale (02 §31 inactive-deal rule).\n  stale_after_days  Int?\n  color             String?\n  created_at        DateTime            @default(now())\n  updated_at        DateTime            @updatedAt\n\n  pipeline     CrmPipeline           @relation(fields: [pipeline_id], references: [id], onDelete: Cascade)\n  deals        CrmDeal[]\n  history_from CrmDealStageHistory[] @relation(\"StageHistoryFrom\")\n  history_to   CrmDealStageHistory[] @relation(\"StageHistoryTo\")\n\n  @@unique([pipeline_id, slug])\n  @@index([pipeline_id, sort_order])\n  @@map(\"crm_pipeline_stages\")\n}\n\n// --- Core records -----------------------------------------------------------\n\n/// 02 §2 — any external legal entity: prospect, customer, partner or vendor. One record model.\n/// Never a platform Organization (01 §8) and never a Branch (01 §16).\nmodel CrmCompany {\n  id                            String         @id @default(uuid())\n  organization_id               String\n  parent_company_id             String?\n  name                          String\n  legal_name                    String?\n  type                          CrmCompanyType @default(PROSPECT)\n  lifecycle_stage_id            String?\n  industry                      String?\n  company_size                  String?\n  number_of_employees           Int?\n  annual_revenue                Decimal?       @db.Decimal(18, 2)\n  currency                      String?\n  website                       String?\n  email                         String?\n  phone                         String?\n  country                       String?\n  address                       Json?\n  tax_id                        String?\n  vat_number                    String?\n  registration_number           String?\n  description                   String?\n  lead_source_id                String?\n  customer_since                DateTime?\n  /// 02 §20 — ownership and responsibility.\n  owner_membership_id           String?\n  account_manager_membership_id String?\n  success_owner_membership_id   String?\n  team_id                       String?\n  /// External system identifiers (02 §27). The billing profile itself is owned by 08.\n  external_ids                  Json?\n  last_activity_at              DateTime?\n  next_activity_at              DateTime?\n  archived_at                   DateTime?\n  created_by_user_id            String?\n  created_at                    DateTime       @default(now())\n  updated_at                    DateTime       @updatedAt\n\n  organization    Organization       @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  parent          CrmCompany?        @relation(\"CrmCompanyHierarchy\", fields: [parent_company_id], references: [id], onDelete: SetNull)\n  children        CrmCompany[]       @relation(\"CrmCompanyHierarchy\")\n  lifecycle_stage CrmLifecycleStage? @relation(fields: [lifecycle_stage_id], references: [id], onDelete: SetNull)\n  lead_source     CrmLeadSource?     @relation(fields: [lead_source_id], references: [id], onDelete: SetNull)\n  owner           Membership?        @relation(\"CrmCompanyOwner\", fields: [owner_membership_id], references: [id], onDelete: SetNull)\n  account_manager Membership?        @relation(\"CrmCompanyAccountManager\", fields: [account_manager_membership_id], references: [id], onDelete: SetNull)\n  success_owner   Membership?        @relation(\"CrmCompanySuccessOwner\", fields: [success_owner_membership_id], references: [id], onDelete: SetNull)\n  team            Team?              @relation(fields: [team_id], references: [id], onDelete: SetNull)\n\n  contacts             CrmContact[]\n  leads                CrmLead[]\n  deals                CrmDeal[]\n  activities           CrmActivity[]\n  branches             CrmCompanyBranch[]\n  lifecycle_history    CrmLifecycleHistory[]\n  converted_from_leads CrmLead[]             @relation(\"LeadConvertedCompany\")\n  proposals            Proposal[]\n  primary_contracts    Contract[]            @relation(\"ContractPrimaryCompany\")\n  contract_parties     ContractParty[]\n  projects             Project[]\n\n  @@index([organization_id, name])\n  @@index([organization_id, type])\n  @@index([organization_id, lifecycle_stage_id])\n  @@index([owner_membership_id])\n  @@index([parent_company_id])\n  @@map(\"crm_companies\")\n}\n\n/// 01 §31, §37 — branch relationships on one company record instead of duplicate companies.\nmodel CrmCompanyBranch {\n  id            String                @id @default(uuid())\n  company_id    String\n  branch_id     String\n  relation_type CrmBranchRelationType @default(SALES)\n  is_primary    Boolean               @default(false)\n  created_at    DateTime              @default(now())\n\n  company CrmCompany @relation(fields: [company_id], references: [id], onDelete: Cascade)\n  branch  Branch     @relation(fields: [branch_id], references: [id], onDelete: Cascade)\n\n  @@unique([company_id, branch_id, relation_type])\n  @@index([branch_id])\n  @@map(\"crm_company_branches\")\n}\n\n/// 02 §3 — a person at a Company. Not a platform User (01 §4).\nmodel CrmContact {\n  id                  String           @id @default(uuid())\n  organization_id     String\n  company_id          String?\n  first_name          String\n  last_name           String?\n  job_title           String?\n  department          String?\n  /// Primary email; additional addresses in `emails`.\n  email               String?\n  emails              Json?\n  phone               String?\n  mobile              String?\n  phones              Json?\n  website             String?\n  linkedin_url        String?\n  social_profiles     Json?\n  roles               CrmContactRole[] @default([])\n  contact_type        String?\n  lifecycle_stage_id  String?\n  lead_source_id      String?\n  owner_membership_id String?\n  timezone            String?\n  language            String?\n  /// Marketing consent per channel (consumed by 11 Communication Center).\n  consent             Json?\n  description         String?\n  last_activity_at    DateTime?\n  archived_at         DateTime?\n  created_by_user_id  String?\n  created_at          DateTime         @default(now())\n  updated_at          DateTime         @updatedAt\n\n  organization    Organization       @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  company         CrmCompany?        @relation(fields: [company_id], references: [id], onDelete: SetNull)\n  lifecycle_stage CrmLifecycleStage? @relation(fields: [lifecycle_stage_id], references: [id], onDelete: SetNull)\n  lead_source     CrmLeadSource?     @relation(fields: [lead_source_id], references: [id], onDelete: SetNull)\n  owner           Membership?        @relation(\"CrmContactOwner\", fields: [owner_membership_id], references: [id], onDelete: SetNull)\n\n  leads                CrmLead[]\n  primary_deals        CrmDeal[]                @relation(\"CrmDealPrimaryContact\")\n  deal_links           CrmDealContact[]\n  activities           CrmActivityParticipant[]\n  lifecycle_history    CrmLifecycleHistory[]\n  converted_from_leads CrmLead[]                @relation(\"LeadConvertedContact\")\n  proposals            Proposal[]\n  proposal_deliveries  ProposalDelivery[]\n  proposal_acceptances ProposalAcceptance[]\n  contract_signatories ContractSignatory[]\n  project_stakeholders ProjectStakeholder[]\n\n  @@index([organization_id, email])\n  @@index([organization_id, last_name, first_name])\n  @@index([company_id])\n  @@index([owner_membership_id])\n  @@map(\"crm_contacts\")\n}\n\n/// 02 §4–7 — prospect before qualification. Conversion links to the created records (02 §7).\nmodel CrmLead {\n  id                     String    @id @default(uuid())\n  organization_id        String\n  branch_id              String?\n  name                   String\n  company_id             String?\n  contact_id             String?\n  /// Free-text company/contact details captured before records exist.\n  company_name           String?\n  contact_name           String?\n  email                  String?\n  phone                  String?\n  website                String?\n  industry               String?\n  estimated_company_size String?\n  estimated_value        Decimal?  @db.Decimal(18, 2)\n  currency               String?\n  status_id              String?\n  lead_source_id         String?\n  owner_membership_id    String?\n  /// 02 §6 — qualification criteria and answers.\n  qualification          Json?\n  qualification_notes    String?\n  lead_score             Int?\n  manual_score           Int?\n  description            String?\n  last_activity_at       DateTime?\n  next_follow_up_at      DateTime?\n  converted_at           DateTime?\n  converted_company_id   String?\n  converted_contact_id   String?\n  converted_deal_id      String?\n  lost_reason            String?\n  archived_at            DateTime?\n  created_by_user_id     String?\n  created_at             DateTime  @default(now())\n  updated_at             DateTime  @updatedAt\n\n  organization      Organization   @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  branch            Branch?        @relation(fields: [branch_id], references: [id], onDelete: SetNull)\n  company           CrmCompany?    @relation(fields: [company_id], references: [id], onDelete: SetNull)\n  contact           CrmContact?    @relation(fields: [contact_id], references: [id], onDelete: SetNull)\n  status            CrmLeadStatus? @relation(fields: [status_id], references: [id], onDelete: SetNull)\n  lead_source       CrmLeadSource? @relation(fields: [lead_source_id], references: [id], onDelete: SetNull)\n  owner             Membership?    @relation(\"CrmLeadOwner\", fields: [owner_membership_id], references: [id], onDelete: SetNull)\n  converted_company CrmCompany?    @relation(\"LeadConvertedCompany\", fields: [converted_company_id], references: [id], onDelete: SetNull)\n  converted_contact CrmContact?    @relation(\"LeadConvertedContact\", fields: [converted_contact_id], references: [id], onDelete: SetNull)\n  converted_deal    CrmDeal?       @relation(\"LeadConvertedDeal\", fields: [converted_deal_id], references: [id], onDelete: SetNull)\n  activities        CrmActivity[]\n\n  @@index([organization_id, status_id])\n  @@index([organization_id, owner_membership_id])\n  @@index([organization_id, email])\n  @@map(\"crm_leads\")\n}\n\n/// 02 §9 — deal / opportunity. Totals derive from line items when any exist (02 §10).\nmodel CrmDeal {\n  id                  String              @id @default(uuid())\n  organization_id     String\n  branch_id           String?\n  pipeline_id         String\n  stage_id            String\n  name                String\n  company_id          String?\n  primary_contact_id  String?\n  owner_membership_id String?\n  team_id             String?\n  status              CrmDealStatus       @default(OPEN)\n  value               Decimal             @default(0) @db.Decimal(18, 2)\n  recurring_value     Decimal             @default(0) @db.Decimal(18, 2)\n  one_time_value      Decimal             @default(0) @db.Decimal(18, 2)\n  discount_amount     Decimal             @default(0) @db.Decimal(18, 2)\n  tax_amount          Decimal             @default(0) @db.Decimal(18, 2)\n  currency            String\n  probability         Int?\n  forecast_category   CrmForecastCategory @default(PIPELINE)\n  expected_close_date DateTime?           @db.Date\n  actual_close_date   DateTime?           @db.Date\n  deal_type           String?\n  lead_source_id      String?\n  competitor          String?\n  lost_reason         String?\n  next_step           String?\n  description         String?\n  /// References to records owned by other modules (ids only): 03, 04, 05.\n  proposal_id         String?\n  contract_id         String?\n  project_id          String?\n  stage_entered_at    DateTime            @default(now())\n  last_activity_at    DateTime?\n  archived_at         DateTime?\n  created_by_user_id  String?\n  created_at          DateTime            @default(now())\n  updated_at          DateTime            @updatedAt\n\n  organization    Organization     @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  branch          Branch?          @relation(fields: [branch_id], references: [id], onDelete: SetNull)\n  pipeline        CrmPipeline      @relation(fields: [pipeline_id], references: [id], onDelete: Restrict)\n  stage           CrmPipelineStage @relation(fields: [stage_id], references: [id], onDelete: Restrict)\n  company         CrmCompany?      @relation(fields: [company_id], references: [id], onDelete: SetNull)\n  primary_contact CrmContact?      @relation(\"CrmDealPrimaryContact\", fields: [primary_contact_id], references: [id], onDelete: SetNull)\n  owner           Membership?      @relation(\"CrmDealOwner\", fields: [owner_membership_id], references: [id], onDelete: SetNull)\n  team            Team?            @relation(fields: [team_id], references: [id], onDelete: SetNull)\n  lead_source     CrmLeadSource?   @relation(fields: [lead_source_id], references: [id], onDelete: SetNull)\n  project         Project?         @relation(\"CrmDealProject\", fields: [project_id], references: [id], onDelete: SetNull)\n\n  contacts             CrmDealContact[]\n  line_items           CrmDealLineItem[]\n  stage_history        CrmDealStageHistory[]\n  activities           CrmActivity[]\n  converted_from_leads CrmLead[]             @relation(\"LeadConvertedDeal\")\n  proposals            Proposal[]\n\n  @@index([organization_id, pipeline_id, stage_id])\n  @@index([organization_id, status])\n  @@index([company_id])\n  @@index([owner_membership_id])\n  @@index([expected_close_date])\n  @@map(\"crm_deals\")\n}\n\n/// 02 §9 — additional contacts on a deal.\nmodel CrmDealContact {\n  deal_id    String\n  contact_id String\n  role       String?\n  created_at DateTime @default(now())\n\n  deal    CrmDeal    @relation(fields: [deal_id], references: [id], onDelete: Cascade)\n  contact CrmContact @relation(fields: [contact_id], references: [id], onDelete: Cascade)\n\n  @@id([deal_id, contact_id])\n  @@index([contact_id])\n  @@map(\"crm_deal_contacts\")\n}\n\n/// 02 §10 — deal line items. product_id references the Finance catalog (08); no FK until 08 exists.\nmodel CrmDealLineItem {\n  id                String   @id @default(uuid())\n  deal_id           String\n  product_id        String?\n  name              String\n  description       String?\n  quantity          Decimal  @default(1) @db.Decimal(12, 3)\n  unit_price        Decimal  @default(0) @db.Decimal(18, 2)\n  discount_percent  Decimal? @db.Decimal(5, 2)\n  discount_amount   Decimal  @default(0) @db.Decimal(18, 2)\n  tax_percent       Decimal? @db.Decimal(5, 2)\n  net_amount        Decimal  @default(0) @db.Decimal(18, 2)\n  tax_amount        Decimal  @default(0) @db.Decimal(18, 2)\n  gross_amount      Decimal  @default(0) @db.Decimal(18, 2)\n  is_recurring      Boolean  @default(false)\n  /// monthly | quarterly | annual | custom\n  billing_frequency String?\n  sort_order        Int      @default(0)\n  created_at        DateTime @default(now())\n  updated_at        DateTime @updatedAt\n\n  deal CrmDeal @relation(fields: [deal_id], references: [id], onDelete: Cascade)\n\n  @@index([deal_id])\n  @@map(\"crm_deal_line_items\")\n}\n\n/// 02 §8, §34 — stage transitions for duration, velocity and history.\nmodel CrmDealStageHistory {\n  id                 String   @id @default(uuid())\n  deal_id            String\n  from_stage_id      String?\n  to_stage_id        String\n  changed_by_user_id String?\n  changed_at         DateTime @default(now())\n  /// Seconds spent in from_stage.\n  duration_seconds   Int?\n\n  deal       CrmDeal           @relation(fields: [deal_id], references: [id], onDelete: Cascade)\n  from_stage CrmPipelineStage? @relation(\"StageHistoryFrom\", fields: [from_stage_id], references: [id], onDelete: SetNull)\n  to_stage   CrmPipelineStage  @relation(\"StageHistoryTo\", fields: [to_stage_id], references: [id], onDelete: Cascade)\n\n  @@index([deal_id, changed_at])\n  @@map(\"crm_deal_stage_history\")\n}\n\n// --- Activities & notes -----------------------------------------------------\n\n/// 02 §12–15 — unified CRM activity. Tasks are NOT activities: they live in 06 and link back to CRM\n/// records from Task Management. MEETING rows reference a Calendar event (19).\nmodel CrmActivity {\n  id                  String            @id @default(uuid())\n  organization_id     String\n  type                CrmActivityType\n  status              CrmActivityStatus @default(PLANNED)\n  priority            CrmPriority       @default(NORMAL)\n  title               String\n  description         String?\n  company_id          String?\n  contact_id          String?\n  lead_id             String?\n  deal_id             String?\n  /// Project reference (05); id only.\n  project_id          String?\n  owner_membership_id String?\n  starts_at           DateTime?\n  ends_at             DateTime?\n  duration_minutes    Int?\n  location            String?\n  meeting_url         String?\n  /// Calendar event id (19); id only.\n  calendar_event_id   String?\n  outcome             String?\n  /// Automation rule id (20) when created by a rule.\n  automation_rule_id  String?\n  completed_at        DateTime?\n  created_by_user_id  String?\n  created_at          DateTime          @default(now())\n  updated_at          DateTime          @updatedAt\n\n  organization Organization             @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  company      CrmCompany?              @relation(fields: [company_id], references: [id], onDelete: Cascade)\n  lead         CrmLead?                 @relation(fields: [lead_id], references: [id], onDelete: Cascade)\n  deal         CrmDeal?                 @relation(fields: [deal_id], references: [id], onDelete: Cascade)\n  owner        Membership?              @relation(\"CrmActivityOwner\", fields: [owner_membership_id], references: [id], onDelete: SetNull)\n  participants CrmActivityParticipant[]\n\n  @@index([organization_id, starts_at])\n  @@index([company_id])\n  @@index([contact_id])\n  @@index([deal_id])\n  @@index([lead_id])\n  @@index([owner_membership_id, status])\n  @@map(\"crm_activities\")\n}\n\n/// Participants of an activity: internal Members (by membership id) and CRM Contacts.\nmodel CrmActivityParticipant {\n  id            String  @id @default(uuid())\n  activity_id   String\n  membership_id String?\n  contact_id    String?\n  response      String?\n\n  activity CrmActivity @relation(fields: [activity_id], references: [id], onDelete: Cascade)\n  contact  CrmContact? @relation(fields: [contact_id], references: [id], onDelete: Cascade)\n\n  @@unique([activity_id, membership_id, contact_id])\n  @@index([contact_id])\n  @@map(\"crm_activity_participants\")\n}\n\n/// 02 §16 — notes attachable to companies, contacts, leads, deals and other modules' records.\nmodel CrmNote {\n  id                   String           @id @default(uuid())\n  organization_id      String\n  entity_type          RecordEntityType\n  entity_id            String\n  author_membership_id String?\n  /// Markdown / rich text body.\n  body                 String\n  is_private           Boolean          @default(false)\n  /// Mentioned membership ids.\n  mentions             String[]         @default([])\n  pinned               Boolean          @default(false)\n  edited_at            DateTime?\n  /// Previous bodies for edit history (02 §16).\n  edit_history         Json?\n  created_at           DateTime         @default(now())\n  updated_at           DateTime         @updatedAt\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  author       Membership?  @relation(\"CrmNoteAuthor\", fields: [author_membership_id], references: [id], onDelete: SetNull)\n\n  @@index([entity_type, entity_id, created_at])\n  @@index([organization_id])\n  @@map(\"crm_notes\")\n}\n\n// --- Operations ---------------------------------------------------------------\n\n/// 02 §20 — automatic assignment rules (evaluated by the Automation Engine, 20).\nmodel CrmAssignmentRule {\n  id              String           @id @default(uuid())\n  organization_id String\n  name            String\n  entity_type     RecordEntityType\n  /// Conditions on record fields and custom fields.\n  conditions      Json\n  /// { membership_id } | { team_id, strategy: \"round_robin\" | \"least_loaded\" }\n  assign_to       Json\n  priority        Int              @default(0)\n  enabled         Boolean          @default(true)\n  created_at      DateTime         @default(now())\n  updated_at      DateTime         @updatedAt\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n\n  @@index([organization_id, entity_type, enabled])\n  @@map(\"crm_assignment_rules\")\n}\n\n/// 02 §22 — CSV import jobs with mapping, preview, validation, history and rollback.\nmodel CrmImportJob {\n  id                       String           @id @default(uuid())\n  organization_id          String\n  entity_type              RecordEntityType\n  status                   CrmImportStatus  @default(PENDING)\n  /// Uploaded file (17 Documents); id only.\n  document_id              String?\n  file_name                String?\n  field_mapping            Json?\n  /// Duplicate detection strategy: match fields and merge behaviour.\n  duplicate_strategy       Json?\n  total_rows               Int              @default(0)\n  imported_rows            Int              @default(0)\n  updated_rows             Int              @default(0)\n  skipped_rows             Int              @default(0)\n  error_rows               Int              @default(0)\n  errors                   Json?\n  /// Ids created by this job, kept for rollback.\n  created_record_ids       String[]         @default([])\n  started_by_membership_id String?\n  started_at               DateTime?\n  completed_at             DateTime?\n  rolled_back_at           DateTime?\n  created_at               DateTime         @default(now())\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  started_by   Membership?  @relation(fields: [started_by_membership_id], references: [id], onDelete: SetNull)\n\n  @@index([organization_id, status])\n  @@map(\"crm_import_jobs\")\n}\n\n// =====================================================================\n// Platform shared concept — document numbering (used by 03 Proposals, 04 Contracts, 08 Finance).\n// =====================================================================\n\n/// Per-organization numbering sequences, e.g. PRO-2026-0001 / CTR-2026-0001 / INV-2026-0001.\n/// Services increment `next_number` inside a transaction; numbers are never reused.\nmodel NumberSequence {\n  id              String   @id @default(uuid())\n  organization_id String\n  /// proposal | contract | invoice | credit_note | ticket …\n  entity_type     String\n  prefix          String\n  /// Null for sequences that do not reset yearly.\n  year            Int?\n  next_number     Int      @default(1)\n  padding         Int      @default(4)\n  updated_at      DateTime @updatedAt\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n\n  @@unique([organization_id, entity_type, prefix, year])\n  @@map(\"number_sequences\")\n}\n\n// =====================================================================\n// 03 AI-Powered Proposal & Quotation Generator — docs/features/03-proposal-quotation-generator.md (LOG-303)\n// Owns: Proposal, versions, sections, line items, payment schedules, templates, internal review,\n// delivery, tracking, customer acceptance, conversion links.\n// Does not own: products catalog and tax rates (08), PDF files (17), signature requests (04),\n// contracts (04), projects (05), invoices/subscriptions (08), emails (11). Referenced by id only.\n// =====================================================================\n\n/// 03 \"Proposal Status\" — lifecycle of the proposal record (the latest/sent version drives it).\nenum ProposalStatus {\n  DRAFT\n  IN_REVIEW\n  PENDING_APPROVAL\n  APPROVED\n  SENT\n  VIEWED\n  CHANGES_REQUESTED\n  ACCEPTED\n  REJECTED\n  EXPIRED\n  CANCELLED\n}\n\n/// 03 \"Proposal Versions\" — a version is immutable once sent.\nenum ProposalVersionStatus {\n  DRAFT\n  IN_REVIEW\n  APPROVED\n  SENT\n  SUPERSEDED\n}\n\n/// 03 \"Proposal Review\" — internal approval decision.\nenum ProposalApprovalDecision {\n  PENDING\n  APPROVED\n  REJECTED\n  CHANGES_REQUESTED\n}\n\n/// 03 \"Customer Approval\".\nenum ProposalCustomerDecision {\n  ACCEPTED\n  REJECTED\n  CHANGES_REQUESTED\n}\n\n/// 03 \"Customer Delivery\".\nenum ProposalDeliveryChannel {\n  EMAIL\n  CUSTOMER_PORTAL\n  PDF\n  LINK\n}\n\nenum ProposalDeliveryStatus {\n  QUEUED\n  SENT\n  DELIVERED\n  FAILED\n}\n\n/// 03 \"Proposal Tracking\" — customer and system events on a proposal.\nenum ProposalEventType {\n  CREATED\n  VERSION_CREATED\n  SUBMITTED_FOR_REVIEW\n  APPROVED\n  SENT\n  VIEWED\n  DOWNLOADED\n  OPTIONAL_ITEM_TOGGLED\n  COMMENTED\n  CHANGES_REQUESTED\n  ACCEPTED\n  REJECTED\n  SIGNED\n  EXPIRED\n  CANCELLED\n  CONVERTED\n}\n\n/// 03 \"Reusable Templates\" / \"Dynamic Proposal Content\" — section types.\nenum ProposalSectionType {\n  COVER\n  EXECUTIVE_SUMMARY\n  OVERVIEW\n  REQUIREMENTS\n  SOLUTION\n  SCOPE\n  FEATURES\n  DELIVERABLES\n  PHASES\n  MILESTONES\n  TIMELINE\n  PRICING\n  PAYMENT_SCHEDULE\n  SUPPORT_OPTIONS\n  ASSUMPTIONS\n  EXCLUSIONS\n  WARRANTY\n  TERMS\n  NEXT_STEPS\n  SIGNATURE\n  CUSTOM\n}\n\n/// 03 \"Pricing & Quotation Builder\" — when a payment schedule item is due.\nenum ProposalPaymentTrigger {\n  ON_ACCEPTANCE\n  ON_SIGNATURE\n  ON_DATE\n  ON_MILESTONE\n  ON_DELIVERY\n  RECURRING\n}\n\n// --- Templates -------------------------------------------------------------------\n\n/// 03 \"Reusable Templates\" — branded, versioned template per work type. Organization-owned.\nmodel ProposalTemplate {\n  id                    String    @id @default(uuid())\n  organization_id       String\n  name                  String\n  slug                  String\n  description           String?\n  /// Work type the template targets (website, web app, mobile, custom software, SaaS, maintenance, support, consulting, …).\n  work_type             String?\n  language              String    @default(\"en\")\n  /// Branding overrides; organization branding (01 §15) is the fallback.\n  branding              Json?\n  /// Page layout: cover page, headers/footers, typography, table styles.\n  layout                Json?\n  /// Ordered section blueprint: [{ type, title, body_template, is_required, sort_order }].\n  sections              Json\n  /// Default terms, warranty, assumptions, exclusions, payment terms text.\n  defaults              Json?\n  /// Dynamic variables the template expects (03 \"Dynamic Proposal Content\").\n  variables             Json?\n  default_validity_days Int       @default(30)\n  is_default            Boolean   @default(false)\n  version               Int       @default(1)\n  archived_at           DateTime?\n  created_by_user_id    String?\n  created_at            DateTime  @default(now())\n  updated_at            DateTime  @updatedAt\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  proposals    Proposal[]\n\n  @@unique([organization_id, slug])\n  @@index([organization_id, work_type])\n  @@map(\"proposal_templates\")\n}\n\n// --- Proposal --------------------------------------------------------------------\n\n/// 03 \"Proposal Creation\" — the proposal record. Content lives in versions; this row carries\n/// identity, relationships, status and snapshots of the current version's totals.\nmodel Proposal {\n  id                   String         @id @default(uuid())\n  organization_id      String\n  branch_id            String?\n  /// Organization numbering, e.g. PRO-2026-0001 (NumberSequence).\n  number               String\n  title                String\n  status               ProposalStatus @default(DRAFT)\n  template_id          String?\n  language             String         @default(\"en\")\n  currency             String\n  /// CRM references (02). company_id is the Customer the proposal is addressed to.\n  company_id           String?\n  contact_id           String?\n  deal_id              String?\n  owner_membership_id  String?\n  /// Project context the proposal was generated from or for (05); id only.\n  project_id           String?\n  /// Validity of the currently sent version.\n  valid_until          DateTime?      @db.Date\n  /// Version pointers.\n  current_version_id   String?        @unique\n  sent_version_id      String?        @unique\n  accepted_version_id  String?        @unique\n  /// Snapshot of current version totals for list views and dashboards.\n  net_total            Decimal        @default(0) @db.Decimal(18, 2)\n  discount_total       Decimal        @default(0) @db.Decimal(18, 2)\n  tax_total            Decimal        @default(0) @db.Decimal(18, 2)\n  gross_total          Decimal        @default(0) @db.Decimal(18, 2)\n  recurring_monthly    Decimal        @default(0) @db.Decimal(18, 2)\n  recurring_annual     Decimal        @default(0) @db.Decimal(18, 2)\n  /// Whether acceptance must produce a Contract before project/billing creation (03 \"Conversion to Project\").\n  requires_contract    Boolean        @default(false)\n  /// Public web view (03 \"Customer Delivery\"): hashed token; expires with valid_until.\n  public_token_hash    String?        @unique\n  /// Conversion links to records owned by other modules (ids only): 04, 05, 08.\n  contract_id          String?\n  converted_project_id String?\n  invoice_id           String?\n  subscription_id      String?\n  converted_at         DateTime?\n  sent_at              DateTime?\n  first_viewed_at      DateTime?\n  last_viewed_at       DateTime?\n  view_count           Int            @default(0)\n  accepted_at          DateTime?\n  rejected_at          DateTime?\n  expired_at           DateTime?\n  cancelled_at         DateTime?\n  archived_at          DateTime?\n  created_by_user_id   String?\n  created_at           DateTime       @default(now())\n  updated_at           DateTime       @updatedAt\n\n  organization      Organization      @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  branch            Branch?           @relation(fields: [branch_id], references: [id], onDelete: SetNull)\n  template          ProposalTemplate? @relation(fields: [template_id], references: [id], onDelete: SetNull)\n  company           CrmCompany?       @relation(fields: [company_id], references: [id], onDelete: SetNull)\n  contact           CrmContact?       @relation(fields: [contact_id], references: [id], onDelete: SetNull)\n  deal              CrmDeal?          @relation(fields: [deal_id], references: [id], onDelete: SetNull)\n  converted_project Project?          @relation(\"ProposalConvertedProject\", fields: [converted_project_id], references: [id], onDelete: SetNull)\n  owner             Membership?       @relation(\"ProposalOwner\", fields: [owner_membership_id], references: [id], onDelete: SetNull)\n  current_version   ProposalVersion?  @relation(\"ProposalCurrentVersion\", fields: [current_version_id], references: [id], onDelete: SetNull)\n  sent_version      ProposalVersion?  @relation(\"ProposalSentVersion\", fields: [sent_version_id], references: [id], onDelete: SetNull)\n  accepted_version  ProposalVersion?  @relation(\"ProposalAcceptedVersion\", fields: [accepted_version_id], references: [id], onDelete: SetNull)\n\n  versions    ProposalVersion[]\n  deliveries  ProposalDelivery[]\n  events      ProposalEvent[]\n  comments    ProposalComment[]\n  acceptances ProposalAcceptance[]\n  contracts   Contract[]\n  projects    Project[]            @relation(\"ProjectSourceProposal\")\n\n  @@unique([organization_id, number])\n  @@index([organization_id, status])\n  @@index([company_id])\n  @@index([deal_id])\n  @@index([owner_membership_id])\n  @@index([valid_until])\n  @@map(\"proposals\")\n}\n\n/// 03 \"Proposal Versions\" — every revision. A version that was sent is immutable; acceptance\n/// is always bound to the exact version sent.\nmodel ProposalVersion {\n  id                 String                @id @default(uuid())\n  proposal_id        String\n  version_number     Int\n  status             ProposalVersionStatus @default(DRAFT)\n  parent_version_id  String?\n  change_summary     String?\n  /// Template version used at generation time.\n  template_version   Int?\n  /// Resolved dynamic variables at generation (03 \"Dynamic Proposal Content\").\n  variables          Json?\n  /// Structured commercial content not covered by sections: payment terms, validity, support options.\n  payment_terms      String?\n  validity_days      Int?\n  /// Milestones and timeline proposed (operational copies are created in 05 on conversion).\n  milestones         Json?\n  timeline           Json?\n  net_total          Decimal               @default(0) @db.Decimal(18, 2)\n  discount_total     Decimal               @default(0) @db.Decimal(18, 2)\n  tax_total          Decimal               @default(0) @db.Decimal(18, 2)\n  gross_total        Decimal               @default(0) @db.Decimal(18, 2)\n  recurring_monthly  Decimal               @default(0) @db.Decimal(18, 2)\n  recurring_annual   Decimal               @default(0) @db.Decimal(18, 2)\n  /// Generated PDF stored in 17 Documents; id only.\n  pdf_document_id    String?\n  /// Integrity hash of the rendered artifact.\n  content_hash       String?\n  is_ai_generated    Boolean               @default(false)\n  /// Model, prompt reference, sources used, review findings (03 \"AI Assistance\", \"Proposal Review\").\n  ai_metadata        Json?\n  locked_at          DateTime?\n  sent_at            DateTime?\n  created_by_user_id String?\n  created_at         DateTime              @default(now())\n  updated_at         DateTime              @updatedAt\n\n  proposal       Proposal          @relation(fields: [proposal_id], references: [id], onDelete: Cascade)\n  parent_version ProposalVersion?  @relation(\"ProposalVersionLineage\", fields: [parent_version_id], references: [id], onDelete: SetNull)\n  child_versions ProposalVersion[] @relation(\"ProposalVersionLineage\")\n\n  current_of         Proposal?          @relation(\"ProposalCurrentVersion\")\n  sent_of            Proposal?          @relation(\"ProposalSentVersion\")\n  accepted_of        Proposal?          @relation(\"ProposalAcceptedVersion\")\n  /// Contracts generated from this exact proposal version (04 §7, §55).\n  contracts          Contract[]\n  signature_requests SignatureRequest[]\n  projects           Project[]          @relation(\"ProjectSourceProposalVersion\")\n\n  sections         ProposalSection[]\n  line_items       ProposalLineItem[]\n  payment_schedule ProposalPaymentScheduleItem[]\n  approvals        ProposalApproval[]\n  deliveries       ProposalDelivery[]\n  events           ProposalEvent[]\n  comments         ProposalComment[]\n  acceptances      ProposalAcceptance[]\n\n  @@unique([proposal_id, version_number])\n  @@index([proposal_id, status])\n  @@map(\"proposal_versions\")\n}\n\n/// Addressable content blocks of a version (03 \"AI Proposal Generation\" output structure).\nmodel ProposalSection {\n  id              String              @id @default(uuid())\n  version_id      String\n  type            ProposalSectionType\n  title           String\n  /// Markdown / rich text. Pricing and payment sections render from line items and schedule.\n  body            String?\n  sort_order      Int                 @default(0)\n  is_ai_generated Boolean             @default(false)\n  /// Hidden from the customer-facing render (internal notes inside a section).\n  is_internal     Boolean             @default(false)\n  created_at      DateTime            @default(now())\n  updated_at      DateTime            @updatedAt\n\n  version  ProposalVersion   @relation(fields: [version_id], references: [id], onDelete: Cascade)\n  comments ProposalComment[]\n\n  @@index([version_id, sort_order])\n  @@map(\"proposal_sections\")\n}\n\n/// 03 \"Pricing & Quotation Builder\" — line items of a version. product_id references the\n/// Finance catalog (08); no FK until 08 exists.\nmodel ProposalLineItem {\n  id                   String   @id @default(uuid())\n  version_id           String\n  product_id           String?\n  /// Optional grouping label (package / phase).\n  group_name           String?\n  name                 String\n  description          String?\n  quantity             Decimal  @default(1) @db.Decimal(12, 3)\n  unit                 String?\n  unit_price           Decimal  @default(0) @db.Decimal(18, 2)\n  discount_percent     Decimal? @db.Decimal(5, 2)\n  discount_amount      Decimal  @default(0) @db.Decimal(18, 2)\n  tax_percent          Decimal? @db.Decimal(5, 2)\n  net_amount           Decimal  @default(0) @db.Decimal(18, 2)\n  tax_amount           Decimal  @default(0) @db.Decimal(18, 2)\n  gross_amount         Decimal  @default(0) @db.Decimal(18, 2)\n  is_recurring         Boolean  @default(false)\n  /// monthly | quarterly | annual | custom\n  billing_frequency    String?\n  /// Customer may choose this item (03 \"Approve specific optional items\").\n  is_optional          Boolean  @default(false)\n  /// Whether the customer selected the optional item on acceptance.\n  selected_by_customer Boolean?\n  sort_order           Int      @default(0)\n  created_at           DateTime @default(now())\n  updated_at           DateTime @updatedAt\n\n  version ProposalVersion @relation(fields: [version_id], references: [id], onDelete: Cascade)\n\n  @@index([version_id, sort_order])\n  @@map(\"proposal_line_items\")\n}\n\n/// 03 \"Pricing & Quotation Builder\" — deposits, milestone payments, custom schedules.\nmodel ProposalPaymentScheduleItem {\n  id             String                 @id @default(uuid())\n  version_id     String\n  name           String\n  trigger        ProposalPaymentTrigger @default(ON_ACCEPTANCE)\n  /// Either a percentage of the gross total or a fixed amount.\n  percentage     Decimal?               @db.Decimal(5, 2)\n  amount         Decimal?               @db.Decimal(18, 2)\n  due_date       DateTime?              @db.Date\n  /// Milestone label this payment is tied to (ON_MILESTONE).\n  milestone_name String?\n  /// For RECURRING: monthly | quarterly | annual.\n  frequency      String?\n  sort_order     Int                    @default(0)\n\n  version ProposalVersion @relation(fields: [version_id], references: [id], onDelete: Cascade)\n\n  @@index([version_id, sort_order])\n  @@map(\"proposal_payment_schedule_items\")\n}\n\n// --- Review, delivery, tracking, acceptance --------------------------------------\n\n/// 03 \"Proposal Review\" — internal approval bound to an exact version (approval rights: 01 §95).\nmodel ProposalApproval {\n  id                     String                   @id @default(uuid())\n  version_id             String\n  approver_membership_id String\n  step                   Int                      @default(1)\n  decision               ProposalApprovalDecision @default(PENDING)\n  comment                String?\n  requested_at           DateTime                 @default(now())\n  decided_at             DateTime?\n\n  version  ProposalVersion @relation(fields: [version_id], references: [id], onDelete: Cascade)\n  approver Membership      @relation(\"ProposalApprover\", fields: [approver_membership_id], references: [id], onDelete: Cascade)\n\n  @@unique([version_id, approver_membership_id, step])\n  @@index([approver_membership_id, decision])\n  @@map(\"proposal_approvals\")\n}\n\n/// Internal and customer comments on a proposal or a section. Customer authors are Customer Portal\n/// Users (01 §79) or the addressed contact; internal comments are never shown to customers.\nmodel ProposalComment {\n  id                   String    @id @default(uuid())\n  proposal_id          String\n  version_id           String?\n  section_id           String?\n  author_membership_id String?\n  author_user_id       String?\n  author_contact_id    String?\n  is_internal          Boolean   @default(true)\n  body                 String\n  resolved_at          DateTime?\n  created_at           DateTime  @default(now())\n  updated_at           DateTime  @updatedAt\n\n  proposal Proposal         @relation(fields: [proposal_id], references: [id], onDelete: Cascade)\n  version  ProposalVersion? @relation(fields: [version_id], references: [id], onDelete: Cascade)\n  section  ProposalSection? @relation(fields: [section_id], references: [id], onDelete: Cascade)\n  author   Membership?      @relation(\"ProposalCommentAuthor\", fields: [author_membership_id], references: [id], onDelete: SetNull)\n\n  @@index([proposal_id, created_at])\n  @@index([section_id])\n  @@map(\"proposal_comments\")\n}\n\n/// 03 \"Customer Delivery\" — each send of a version through a channel. Emails go through 11.\nmodel ProposalDelivery {\n  id                   String                  @id @default(uuid())\n  proposal_id          String\n  version_id           String\n  channel              ProposalDeliveryChannel\n  status               ProposalDeliveryStatus  @default(QUEUED)\n  recipient_contact_id String?\n  recipient_email      String?\n  /// Communication record id (11); id only.\n  communication_id     String?\n  sent_by_user_id      String?\n  message              String?\n  sent_at              DateTime?\n  delivered_at         DateTime?\n  failed_reason        String?\n  created_at           DateTime                @default(now())\n\n  proposal  Proposal        @relation(fields: [proposal_id], references: [id], onDelete: Cascade)\n  version   ProposalVersion @relation(fields: [version_id], references: [id], onDelete: Cascade)\n  recipient CrmContact?     @relation(fields: [recipient_contact_id], references: [id], onDelete: SetNull)\n\n  @@index([proposal_id, sent_at])\n  @@map(\"proposal_deliveries\")\n}\n\n/// 03 \"Proposal Tracking\" — append-only event log of customer activity and lifecycle changes.\nmodel ProposalEvent {\n  id               String            @id @default(uuid())\n  proposal_id      String\n  version_id       String?\n  type             ProposalEventType\n  /// Internal actor (user id) or customer actor (portal user id / contact id).\n  actor_user_id    String?\n  actor_contact_id String?\n  ip_address       String?\n  user_agent       String?\n  metadata         Json?\n  created_at       DateTime          @default(now())\n\n  proposal Proposal         @relation(fields: [proposal_id], references: [id], onDelete: Cascade)\n  version  ProposalVersion? @relation(fields: [version_id], references: [id], onDelete: Cascade)\n\n  @@index([proposal_id, created_at])\n  @@index([type, created_at])\n  @@map(\"proposal_events\")\n}\n\n/// 03 \"Customer Approval\" — the customer's decision on an exact version, with the evidence\n/// collected (name, contact, terms confirmation, selected optional items, signature reference).\nmodel ProposalAcceptance {\n  id                         String                   @id @default(uuid())\n  proposal_id                String\n  version_id                 String\n  decision                   ProposalCustomerDecision\n  /// Customer Portal User (01 §79) when accepted through the portal; id only.\n  customer_user_id           String?\n  contact_id                 String?\n  signer_name                String\n  signer_email               String\n  signer_title               String?\n  terms_accepted             Boolean                  @default(false)\n  /// Ids of optional line items the customer selected.\n  selected_optional_item_ids String[]                 @default([])\n  feedback                   String?\n  /// Signature request id from the e-signature provider abstraction (04 §33–38); id only.\n  signature_request_id       String?\n  signature_metadata         Json?\n  ip_address                 String?\n  user_agent                 String?\n  created_at                 DateTime                 @default(now())\n\n  proposal Proposal        @relation(fields: [proposal_id], references: [id], onDelete: Cascade)\n  version  ProposalVersion @relation(fields: [version_id], references: [id], onDelete: Cascade)\n  contact  CrmContact?     @relation(fields: [contact_id], references: [id], onDelete: SetNull)\n\n  @@index([proposal_id, created_at])\n  @@index([version_id])\n  @@map(\"proposal_acceptances\")\n}\n\n// =====================================================================\n// 04 Contracts — docs/features/04-contracts.md (LOG-349)\n// Owns: contract types, templates and clause library, contract records, parties and signatories,\n// versions and sections, review, change requests, approval, e-signature provider abstraction\n// (also used by 03 Proposals), amendments/renewals lineage, obligations, termination.\n// Does not own: projects (05), documents storage (17), invoices (08), calendar events (19),\n// notifications (14), automation (20). Referenced by id only.\n// =====================================================================\n\n/// 04 §5 — contract lifecycle states.\nenum ContractStatus {\n  DRAFT\n  INTERNAL_REVIEW\n  CUSTOMER_REVIEW\n  APPROVAL_REQUIRED\n  READY_FOR_SIGNATURE\n  PARTIALLY_SIGNED\n  FULLY_SIGNED\n  ACTIVE\n  EXPIRING\n  RENEWED\n  SUPERSEDED\n  TERMINATED\n  EXPIRED\n  CANCELLED\n  ARCHIVED\n}\n\n/// 04 §19–20, §80 — version/document state, separate from contract lifecycle.\nenum ContractVersionStatus {\n  DRAFT\n  IN_REVIEW\n  APPROVED\n  LOCKED_FOR_SIGNATURE\n  SIGNED\n  SUPERSEDED\n}\n\n/// 04 §43, §46–48 — how a contract relates to its parent contract.\nenum ContractRelationKind {\n  STANDALONE\n  AMENDMENT\n  RENEWAL\n  SOW\n  CHANGE_ORDER\n  TERMINATION_AGREEMENT\n}\n\n/// 04 §3 — renewal behaviour.\nenum ContractRenewalType {\n  NONE\n  MANUAL\n  AUTOMATIC\n  EVERGREEN\n}\n\n/// 04 §4 — party type.\nenum ContractPartyType {\n  AGENCY\n  CUSTOMER\n  VENDOR\n  PARTNER\n  CONTRACTOR\n  EMPLOYEE\n  OTHER\n}\n\n/// 04 §8, §77 — template governance.\nenum ContractTemplateStatus {\n  DRAFT\n  PUBLISHED\n  DEPRECATED\n}\n\n/// 04 §11–12 — clause status.\nenum ContractClauseStatus {\n  DRAFT\n  ACTIVE\n  DEPRECATED\n}\n\n/// 04 §23 — review decision.\nenum ContractReviewDecision {\n  PENDING\n  APPROVED\n  REJECTED\n  CHANGES_REQUESTED\n}\n\n/// 04 §27–29 — approval decision.\nenum ContractApprovalDecision {\n  PENDING\n  APPROVED\n  REJECTED\n}\n\n/// 04 §26 — contract change request status.\nenum ContractChangeRequestStatus {\n  REQUESTED\n  UNDER_REVIEW\n  ACCEPTED\n  REJECTED\n  IMPLEMENTED\n  WITHDRAWN\n}\n\n/// 04 §49–50 — obligation types.\nenum ContractObligationType {\n  DELIVERABLE\n  PAYMENT\n  REPORTING\n  RENEWAL_NOTICE\n  SLA\n  SECURITY_REVIEW\n  CUSTOMER_APPROVAL\n  OTHER\n}\n\nenum ContractObligationStatus {\n  OPEN\n  IN_PROGRESS\n  FULFILLED\n  OVERDUE\n  WAIVED\n  CANCELLED\n}\n\n/// 04 §75 — AI-extracted obligations need review before acting.\nenum ExtractionReviewState {\n  PENDING_REVIEW\n  CONFIRMED\n  REJECTED\n}\n\n/// 04 §53 — termination type.\nenum ContractTerminationType {\n  FOR_CONVENIENCE\n  FOR_CAUSE\n  MUTUAL\n  EXPIRY\n  OTHER\n}\n\n/// 04 §74 — explainable risk level; not legal advice.\nenum ContractRiskLevel {\n  LOW\n  MEDIUM\n  HIGH\n  CRITICAL\n}\n\n/// 04 §33 — signature providers behind the abstraction.\nenum SignatureProvider {\n  INTERNAL\n  DOCUSIGN\n  DROPBOX_SIGN\n  ADOBE_SIGN\n  OTHER\n}\n\n/// What a signature request is bound to. The version relationship is immutable (04 §34).\nenum SignatureSubjectType {\n  CONTRACT_VERSION\n  PROPOSAL_VERSION\n}\n\n/// 04 §32 — signing order.\nenum SigningOrder {\n  SEQUENTIAL\n  PARALLEL\n}\n\n/// 04 §35 — signature request states.\nenum SignatureRequestStatus {\n  NOT_SENT\n  SENT\n  DELIVERED\n  VIEWED\n  PARTIALLY_SIGNED\n  FULLY_SIGNED\n  DECLINED\n  EXPIRED\n  CANCELLED\n  FAILED\n}\n\nenum SignerStatus {\n  PENDING\n  SENT\n  DELIVERED\n  VIEWED\n  SIGNED\n  DECLINED\n  BOUNCED\n}\n\n/// 04 §38 — provider events retained for the audit trail.\nenum SignatureEventType {\n  REQUEST_CREATED\n  SENT\n  DELIVERED\n  VIEWED\n  SIGNED\n  DECLINED\n  REMINDER_SENT\n  CANCELLED\n  EXPIRED\n  COMPLETED\n  FAILED\n}\n\n// --- Configuration: types, templates, clauses, approval rules ---------------------\n\n/// 04 §2 — configurable contract types with defaults.\nmodel ContractType {\n  id                     String              @id @default(uuid())\n  organization_id        String\n  name                   String\n  slug                   String\n  description            String?\n  default_template_id    String?\n  /// Required metadata keys for this type (04 §16 validation).\n  required_metadata      Json?\n  /// Default approval workflow steps when no ContractApprovalRule matches (04 §27).\n  approval_workflow      Json?\n  /// Signature requirements: required parties, signing order, internal/external first.\n  signature_requirements Json?\n  default_renewal_type   ContractRenewalType @default(NONE)\n  default_notice_days    Int?\n  /// Expiration reminder windows in days (04 §52), e.g. [180,120,90,60,30,14,7].\n  reminder_windows_days  Int[]               @default([90, 60, 30, 14, 7])\n  /// Retention in days after closeout (04 §84); null = organization default.\n  retention_days         Int?\n  sort_order             Int                 @default(0)\n  archived_at            DateTime?\n  created_at             DateTime            @default(now())\n  updated_at             DateTime            @updatedAt\n\n  organization     Organization       @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  default_template ContractTemplate?  @relation(\"ContractTypeDefaultTemplate\", fields: [default_template_id], references: [id], onDelete: SetNull)\n  templates        ContractTemplate[] @relation(\"ContractTemplateType\")\n  contracts        Contract[]\n\n  @@unique([organization_id, slug])\n  @@map(\"contract_types\")\n}\n\n/// 04 §8, §77 — reusable contractual structure. Content is versioned in ContractTemplateVersion;\n/// changing a template never modifies existing contracts.\nmodel ContractTemplate {\n  id                  String                 @id @default(uuid())\n  organization_id     String\n  type_id             String?\n  name                String\n  slug                String\n  description         String?\n  language            String                 @default(\"en\")\n  status              ContractTemplateStatus @default(DRAFT)\n  current_version_id  String?                @unique\n  owner_membership_id String?\n  effective_date      DateTime?              @db.Date\n  deprecated_at       DateTime?\n  created_at          DateTime               @default(now())\n  updated_at          DateTime               @updatedAt\n\n  organization      Organization              @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  type              ContractType?             @relation(\"ContractTemplateType\", fields: [type_id], references: [id], onDelete: SetNull)\n  current_version   ContractTemplateVersion?  @relation(\"ContractTemplateCurrentVersion\", fields: [current_version_id], references: [id], onDelete: SetNull)\n  versions          ContractTemplateVersion[]\n  default_for_types ContractType[]            @relation(\"ContractTypeDefaultTemplate\")\n  contracts         Contract[]\n\n  @@unique([organization_id, slug])\n  @@index([organization_id, status])\n  @@map(\"contract_templates\")\n}\n\n/// 04 §8–10, §14 — one immutable template version: sections, variables, conditional clause rules,\n/// signature blocks, required fields, appendices.\nmodel ContractTemplateVersion {\n  id                 String    @id @default(uuid())\n  template_id        String\n  version_number     Int\n  change_summary     String?\n  /// Ordered sections: [{ key, title, body, clause_key?, conditions?, is_optional, sort_order }].\n  sections           Json\n  /// Variables with source mapping (04 §9): [{ key, label, source, required }].\n  variables          Json?\n  /// Deterministic conditional clause rules (04 §10).\n  conditional_rules  Json?\n  /// Signature blocks per party (04 §31).\n  signature_blocks   Json?\n  required_fields    String[]  @default([])\n  published_at       DateTime?\n  created_by_user_id String?\n  created_at         DateTime  @default(now())\n\n  template   ContractTemplate  @relation(fields: [template_id], references: [id], onDelete: Cascade)\n  current_of ContractTemplate? @relation(\"ContractTemplateCurrentVersion\")\n  versions   ContractVersion[]\n\n  @@unique([template_id, version_number])\n  @@map(\"contract_template_versions\")\n}\n\n/// 04 §11 — clause library entry. Text lives in ContractClauseVersion (04 §12).\nmodel ContractClause {\n  id                  String               @id @default(uuid())\n  organization_id     String\n  key                 String\n  name                String\n  /// payment | ip | confidentiality | privacy | liability | warranty | termination | renewal | sla | security | governing_law | other\n  category            String\n  description         String?\n  status              ContractClauseStatus @default(DRAFT)\n  /// Usage restrictions (04 §11): allowed contract types, jurisdictions, requires approval.\n  usage_restrictions  Json?\n  owner_membership_id String?\n  current_version_id  String?              @unique\n  effective_date      DateTime?            @db.Date\n  deprecated_at       DateTime?\n  created_at          DateTime             @default(now())\n  updated_at          DateTime             @updatedAt\n\n  organization    Organization            @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  current_version ContractClauseVersion?  @relation(\"ContractClauseCurrentVersion\", fields: [current_version_id], references: [id], onDelete: SetNull)\n  versions        ContractClauseVersion[]\n\n  @@unique([organization_id, key])\n  @@index([organization_id, category])\n  @@map(\"contract_clauses\")\n}\n\n/// 04 §12 — a generated contract keeps the exact clause version used.\nmodel ContractClauseVersion {\n  id                 String    @id @default(uuid())\n  clause_id          String\n  version_number     Int\n  text               String\n  change_summary     String?\n  effective_date     DateTime? @db.Date\n  deprecated_at      DateTime?\n  created_by_user_id String?\n  created_at         DateTime  @default(now())\n\n  clause     ContractClause    @relation(fields: [clause_id], references: [id], onDelete: Cascade)\n  current_of ContractClause?   @relation(\"ContractClauseCurrentVersion\")\n  sections   ContractSection[]\n\n  @@unique([clause_id, version_number])\n  @@map(\"contract_clause_versions\")\n}\n\n/// 04 §28 — approval requirements by value, type, liability, discount, payment terms, duration,\n/// customer category, risk, custom fields.\nmodel ContractApprovalRule {\n  id              String   @id @default(uuid())\n  organization_id String\n  name            String\n  /// Predicate on contract metadata.\n  conditions      Json\n  /// Ordered steps: [{ step, approver: { membership_id | role_slug | team_id }, required }].\n  steps           Json\n  priority        Int      @default(0)\n  enabled         Boolean  @default(true)\n  created_at      DateTime @default(now())\n  updated_at      DateTime @updatedAt\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n\n  @@index([organization_id, enabled])\n  @@map(\"contract_approval_rules\")\n}\n\n// --- Contract record ------------------------------------------------------------\n\n/// 04 §3 — the structured business record. Document content lives in versions.\nmodel Contract {\n  id                        String               @id @default(uuid())\n  organization_id           String\n  branch_id                 String?\n  /// Organization numbering, e.g. CTR-2026-0001 (NumberSequence).\n  number                    String\n  title                     String\n  type_id                   String?\n  template_id               String?\n  status                    ContractStatus       @default(DRAFT)\n  relation_kind             ContractRelationKind @default(STANDALONE)\n  /// Original / parent agreement for amendments, renewals, SOWs and change orders (04 §43–48).\n  parent_contract_id        String?\n  /// Sequence inside the parent (Amendment 1, Amendment 2 …).\n  relation_sequence         Int?\n  /// 04 §47 — the contract that replaced this one.\n  superseded_by_contract_id String?              @unique\n  owner_membership_id       String?\n  /// 04 §4 — primary customer (CRM Company, 02). Full party list in ContractParty.\n  primary_company_id        String?\n  /// 04 §7, §55 — source proposal and exact version (03).\n  proposal_id               String?\n  proposal_version_id       String?\n  /// 04 §43 — originating project change request (05); id only.\n  project_change_request_id String?\n  currency                  String?\n  // 04 §51 — independently addressable dates.\n  draft_date                DateTime?            @db.Date\n  approval_date             DateTime?            @db.Date\n  signature_date            DateTime?            @db.Date\n  effective_date            DateTime?            @db.Date\n  start_date                DateTime?            @db.Date\n  end_date                  DateTime?            @db.Date\n  renewal_date              DateTime?            @db.Date\n  notice_deadline           DateTime?            @db.Date\n  expiration_date           DateTime?            @db.Date\n  termination_date          DateTime?            @db.Date\n  renewal_type              ContractRenewalType  @default(NONE)\n  renewal_term_months       Int?\n  notice_days               Int?\n  // 04 §54 — contractual value context; Finance (08) is authoritative for actual billing.\n  total_value               Decimal?             @db.Decimal(18, 2)\n  one_time_value            Decimal?             @db.Decimal(18, 2)\n  recurring_value           Decimal?             @db.Decimal(18, 2)\n  /// monthly | quarterly | annual | milestone | custom\n  billing_frequency         String?\n  payment_terms             String?\n  // 04 §74 — risk scoring.\n  risk_score                Int?\n  risk_level                ContractRiskLevel?\n  risk_factors              Json?\n  /// 04 §61 — portal exposure.\n  customer_visible          Boolean              @default(false)\n  current_version_id        String?              @unique\n  signed_version_id         String?              @unique\n  /// Flags the contract as containing personal-data processing (drives DPA clause, 04 §10).\n  processes_personal_data   Boolean              @default(false)\n  activated_at              DateTime?\n  closed_at                 DateTime?\n  archived_at               DateTime?\n  created_by_user_id        String?\n  created_at                DateTime             @default(now())\n  updated_at                DateTime             @updatedAt\n\n  organization     Organization      @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  branch           Branch?           @relation(fields: [branch_id], references: [id], onDelete: SetNull)\n  type             ContractType?     @relation(fields: [type_id], references: [id], onDelete: SetNull)\n  template         ContractTemplate? @relation(fields: [template_id], references: [id], onDelete: SetNull)\n  parent           Contract?         @relation(\"ContractLineage\", fields: [parent_contract_id], references: [id], onDelete: SetNull)\n  children         Contract[]        @relation(\"ContractLineage\")\n  superseded_by    Contract?         @relation(\"ContractSupersession\", fields: [superseded_by_contract_id], references: [id], onDelete: SetNull)\n  supersedes       Contract?         @relation(\"ContractSupersession\")\n  owner            Membership?       @relation(\"ContractOwner\", fields: [owner_membership_id], references: [id], onDelete: SetNull)\n  primary_company  CrmCompany?       @relation(\"ContractPrimaryCompany\", fields: [primary_company_id], references: [id], onDelete: SetNull)\n  proposal         Proposal?         @relation(fields: [proposal_id], references: [id], onDelete: SetNull)\n  proposal_version ProposalVersion?  @relation(fields: [proposal_version_id], references: [id], onDelete: SetNull)\n  current_version  ContractVersion?  @relation(\"ContractCurrentVersion\", fields: [current_version_id], references: [id], onDelete: SetNull)\n  signed_version   ContractVersion?  @relation(\"ContractSignedVersion\", fields: [signed_version_id], references: [id], onDelete: SetNull)\n\n  parties            ContractParty[]\n  versions           ContractVersion[]\n  projects           ContractProject[]\n  change_requests    ContractChangeRequest[]\n  obligations        ContractObligation[]\n  termination        ContractTermination?\n  signature_requests SignatureRequest[]\n\n  @@unique([organization_id, number])\n  @@index([organization_id, status])\n  @@index([primary_company_id])\n  @@index([parent_contract_id])\n  @@index([expiration_date])\n  @@index([renewal_date])\n  @@index([notice_deadline])\n  @@map(\"contracts\")\n}\n\n/// 04 §4 — a party to the contract. References a CRM Company (02) without duplicating it;\n/// the agency itself is a party of type AGENCY.\nmodel ContractParty {\n  id                  String            @id @default(uuid())\n  contract_id         String\n  party_type          ContractPartyType\n  company_id          String?\n  legal_name          String\n  address             Json?\n  registration_number String?\n  vat_number          String?\n  sort_order          Int               @default(0)\n  created_at          DateTime          @default(now())\n\n  contract    Contract            @relation(fields: [contract_id], references: [id], onDelete: Cascade)\n  company     CrmCompany?         @relation(fields: [company_id], references: [id], onDelete: SetNull)\n  signatories ContractSignatory[]\n\n  @@index([contract_id])\n  @@index([company_id])\n  @@map(\"contract_parties\")\n}\n\n/// 04 §4, §31 — a signatory for a party; a party may have several. Internal signatories are Members,\n/// external ones are CRM Contacts or free-text.\nmodel ContractSignatory {\n  id            String   @id @default(uuid())\n  party_id      String\n  membership_id String?\n  contact_id    String?\n  name          String\n  title         String?\n  email         String\n  is_required   Boolean  @default(true)\n  sort_order    Int      @default(0)\n  created_at    DateTime @default(now())\n\n  party      ContractParty @relation(fields: [party_id], references: [id], onDelete: Cascade)\n  membership Membership?   @relation(fields: [membership_id], references: [id], onDelete: SetNull)\n  contact    CrmContact?   @relation(fields: [contact_id], references: [id], onDelete: SetNull)\n  signers    Signer[]\n\n  @@index([party_id])\n  @@map(\"contract_signatories\")\n}\n\n/// 04 §56 — a contract can reference many projects (05).\nmodel ContractProject {\n  contract_id String\n  project_id  String\n  /// primary | sow | related\n  role        String   @default(\"primary\")\n  created_at  DateTime @default(now())\n\n  contract Contract @relation(fields: [contract_id], references: [id], onDelete: Cascade)\n  project  Project  @relation(fields: [project_id], references: [id], onDelete: Cascade)\n\n  @@id([contract_id, project_id])\n  @@index([project_id])\n  @@map(\"contract_projects\")\n}\n\n// --- Versions ----------------------------------------------------------------------\n\n/// 04 §19–20 — every material draft change creates a version. Signed versions are immutable (04 §39).\nmodel ContractVersion {\n  id                  String                @id @default(uuid())\n  contract_id         String\n  version_number      Int\n  /// Display label, e.g. \"v0.3\", \"v1.0\", \"Amendment 1\" (04 §19).\n  label               String\n  parent_version_id   String?\n  status              ContractVersionStatus @default(DRAFT)\n  change_summary      String?\n  template_version_id String?\n  /// Resolved variables at generation (04 §9, §17).\n  variables           Json?\n  /// Rendered document in 17 Documents (draft artifact); id only.\n  document_id         String?\n  /// Final signed artifact in 17 Documents (04 §41); id only.\n  signed_document_id  String?\n  /// Integrity hash of the rendered / signed artifact (04 §17, §40).\n  content_hash        String?\n  signed_hash         String?\n  /// Whether the customer may see this version in the portal (04 §24, §61).\n  customer_visible    Boolean               @default(false)\n  locked_at           DateTime?\n  approved_at         DateTime?\n  signed_at           DateTime?\n  created_by_user_id  String?\n  created_at          DateTime              @default(now())\n  updated_at          DateTime              @updatedAt\n\n  contract         Contract                 @relation(fields: [contract_id], references: [id], onDelete: Cascade)\n  parent_version   ContractVersion?         @relation(\"ContractVersionLineage\", fields: [parent_version_id], references: [id], onDelete: SetNull)\n  child_versions   ContractVersion[]        @relation(\"ContractVersionLineage\")\n  template_version ContractTemplateVersion? @relation(fields: [template_version_id], references: [id], onDelete: SetNull)\n\n  current_of Contract? @relation(\"ContractCurrentVersion\")\n  signed_of  Contract? @relation(\"ContractSignedVersion\")\n\n  sections             ContractSection[]\n  reviews              ContractReview[]\n  comments             ContractComment[]\n  approvals            ContractApproval[]\n  signature_requests   SignatureRequest[]\n  change_requests_from ContractChangeRequest[] @relation(\"ChangeRequestRelatedVersion\")\n  change_requests_to   ContractChangeRequest[] @relation(\"ChangeRequestResultingVersion\")\n\n  @@unique([contract_id, version_number])\n  @@index([contract_id, status])\n  @@map(\"contract_versions\")\n}\n\n/// 04 §14 — addressable section of a version; may embed an exact clause version (04 §12).\nmodel ContractSection {\n  id                String   @id @default(uuid())\n  version_id        String\n  /// Stable key within the contract (parties, definitions, scope, fees, ip, …).\n  key               String\n  title             String\n  body              String?\n  clause_version_id String?\n  /// Appendix / schedule marker.\n  is_appendix       Boolean  @default(false)\n  sort_order        Int      @default(0)\n  created_at        DateTime @default(now())\n  updated_at        DateTime @updatedAt\n\n  version         ContractVersion         @relation(fields: [version_id], references: [id], onDelete: Cascade)\n  clause_version  ContractClauseVersion?  @relation(fields: [clause_version_id], references: [id], onDelete: SetNull)\n  comments        ContractComment[]\n  change_requests ContractChangeRequest[]\n  obligations     ContractObligation[]\n\n  @@unique([version_id, key])\n  @@index([version_id, sort_order])\n  @@map(\"contract_sections\")\n}\n\n// --- Review, comments, change requests, approval ----------------------------------\n\n/// 04 §23–24 — a review request references one exact version. Internal reviewers are Members;\n/// customer reviewers are Customer Portal Users (id only) or contacts.\nmodel ContractReview {\n  id                     String                 @id @default(uuid())\n  version_id             String\n  reviewer_membership_id String?\n  reviewer_user_id       String?\n  is_internal            Boolean                @default(true)\n  decision               ContractReviewDecision @default(PENDING)\n  comment                String?\n  requested_by_user_id   String?\n  requested_at           DateTime               @default(now())\n  due_at                 DateTime?\n  decided_at             DateTime?\n\n  version  ContractVersion @relation(fields: [version_id], references: [id], onDelete: Cascade)\n  reviewer Membership?     @relation(\"ContractReviewer\", fields: [reviewer_membership_id], references: [id], onDelete: Cascade)\n\n  @@index([version_id, decision])\n  @@index([reviewer_membership_id, decision])\n  @@map(\"contract_reviews\")\n}\n\n/// 04 §13, §23–24 — comments on a version or section; internal comments never reach the portal.\nmodel ContractComment {\n  id                   String    @id @default(uuid())\n  version_id           String\n  section_id           String?\n  author_membership_id String?\n  author_user_id       String?\n  is_internal          Boolean   @default(true)\n  /// Blocks signature until resolved (04 §30).\n  is_blocking          Boolean   @default(false)\n  body                 String\n  resolved_at          DateTime?\n  resolved_by_user_id  String?\n  created_at           DateTime  @default(now())\n  updated_at           DateTime  @updatedAt\n\n  version ContractVersion  @relation(fields: [version_id], references: [id], onDelete: Cascade)\n  section ContractSection? @relation(fields: [section_id], references: [id], onDelete: Cascade)\n  author  Membership?      @relation(\"ContractCommentAuthor\", fields: [author_membership_id], references: [id], onDelete: SetNull)\n\n  @@index([version_id, created_at])\n  @@index([section_id])\n  @@map(\"contract_comments\")\n}\n\n/// 04 §26 — Contract Change Request: a request to change contract language. Never mutates the\n/// current version; an accepted request produces a new version or an amendment.\nmodel ContractChangeRequest {\n  id                        String                      @id @default(uuid())\n  contract_id               String\n  related_version_id        String?\n  resulting_version_id      String?\n  section_id                String?\n  requester_membership_id   String?\n  requester_user_id         String?\n  requester_contact_id      String?\n  requested_change          String\n  reason                    String?\n  impact                    String?\n  status                    ContractChangeRequestStatus @default(REQUESTED)\n  /// Linked Project Change Request (05 §45); id only.\n  project_change_request_id String?\n  decided_by_user_id        String?\n  decided_at                DateTime?\n  created_at                DateTime                    @default(now())\n  updated_at                DateTime                    @updatedAt\n\n  contract          Contract         @relation(fields: [contract_id], references: [id], onDelete: Cascade)\n  related_version   ContractVersion? @relation(\"ChangeRequestRelatedVersion\", fields: [related_version_id], references: [id], onDelete: SetNull)\n  resulting_version ContractVersion? @relation(\"ChangeRequestResultingVersion\", fields: [resulting_version_id], references: [id], onDelete: SetNull)\n  section           ContractSection? @relation(fields: [section_id], references: [id], onDelete: SetNull)\n\n  @@index([contract_id, status])\n  @@map(\"contract_change_requests\")\n}\n\n/// 04 §27–29 — business approval bound to an exact version. Approval of v1.0 does not approve v1.1.\nmodel ContractApproval {\n  id                     String                   @id @default(uuid())\n  version_id             String\n  step                   Int                      @default(1)\n  /// Role label for the step (account owner, finance, legal, executive, technical).\n  step_name              String?\n  approver_membership_id String\n  decision               ContractApprovalDecision @default(PENDING)\n  comment                String?\n  rule_id                String?\n  requested_at           DateTime                 @default(now())\n  decided_at             DateTime?\n\n  version  ContractVersion @relation(fields: [version_id], references: [id], onDelete: Cascade)\n  approver Membership      @relation(\"ContractApprover\", fields: [approver_membership_id], references: [id], onDelete: Cascade)\n\n  @@unique([version_id, approver_membership_id, step])\n  @@index([approver_membership_id, decision])\n  @@map(\"contract_approvals\")\n}\n\n// --- E-signature provider abstraction (04 §30–42, §71, §78–79) -------------------\n\n/// 04 §34 — a signature request bound immutably to one subject version (contract or proposal).\n/// Provider-specific data stays in provider_* fields and metadata, never in core contract fields.\nmodel SignatureRequest {\n  id                            String                 @id @default(uuid())\n  organization_id               String\n  subject_type                  SignatureSubjectType\n  contract_id                   String?\n  contract_version_id           String?\n  proposal_version_id           String?\n  provider                      SignatureProvider      @default(INTERNAL)\n  provider_request_id           String?\n  status                        SignatureRequestStatus @default(NOT_SENT)\n  signing_order                 SigningOrder           @default(SEQUENTIAL)\n  /// 04 §78 — package of document ids (17) in locked order: [{ document_id, title, sort_order }].\n  package_documents             Json?\n  /// 04 §37 — reminder settings: { frequency_days, max_reminders }.\n  reminder_settings             Json?\n  reminders_sent                Int                    @default(0)\n  /// Signed artifact (17) and provider audit certificate (17); ids only.\n  signed_document_id            String?\n  audit_certificate_document_id String?\n  signed_hash                   String?\n  message                       String?\n  created_by_user_id            String?\n  sent_at                       DateTime?\n  expires_at                    DateTime?\n  completed_at                  DateTime?\n  cancelled_at                  DateTime?\n  cancel_reason                 String?\n  metadata                      Json?\n  created_at                    DateTime               @default(now())\n  updated_at                    DateTime               @updatedAt\n\n  organization     Organization     @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  contract         Contract?        @relation(fields: [contract_id], references: [id], onDelete: Cascade)\n  contract_version ContractVersion? @relation(fields: [contract_version_id], references: [id], onDelete: Cascade)\n  proposal_version ProposalVersion? @relation(fields: [proposal_version_id], references: [id], onDelete: Cascade)\n  signers          Signer[]\n  events           SignatureEvent[]\n\n  @@unique([provider, provider_request_id])\n  @@index([organization_id, status])\n  @@index([contract_id])\n  @@index([contract_version_id])\n  @@index([proposal_version_id])\n  @@index([expires_at])\n  @@map(\"signature_requests\")\n}\n\n/// 04 §31–32, §36 — a signer on a request with mapped fields and signing position.\nmodel Signer {\n  id                 String       @id @default(uuid())\n  request_id         String\n  signatory_id       String?\n  name               String\n  email              String\n  title              String?\n  /// Position in sequential signing; equal values sign in parallel.\n  order              Int          @default(1)\n  status             SignerStatus @default(PENDING)\n  /// Mapped fields (04 §31): [{ type: signature|date|initial|text, page, x, y, w, h, required }].\n  fields             Json?\n  /// Signing link token hash for INTERNAL provider; providers supply their own links.\n  access_token_hash  String?      @unique\n  provider_signer_id String?\n  auth_method        String?\n  ip_address         String?\n  user_agent         String?\n  sent_at            DateTime?\n  viewed_at          DateTime?\n  signed_at          DateTime?\n  declined_at        DateTime?\n  decline_reason     String?\n\n  request   SignatureRequest   @relation(fields: [request_id], references: [id], onDelete: Cascade)\n  signatory ContractSignatory? @relation(fields: [signatory_id], references: [id], onDelete: SetNull)\n  events    SignatureEvent[]\n\n  @@index([request_id, order])\n  @@index([email])\n  @@map(\"signers\")\n}\n\n/// 04 §38, §71 — provider and internal events; (provider, provider_event_id) is unique so duplicate\n/// callbacks are ignored.\nmodel SignatureEvent {\n  id                String             @id @default(uuid())\n  request_id        String\n  signer_id         String?\n  type              SignatureEventType\n  provider          SignatureProvider  @default(INTERNAL)\n  provider_event_id String?\n  occurred_at       DateTime           @default(now())\n  ip_address        String?\n  payload           Json?\n  created_at        DateTime           @default(now())\n\n  request SignatureRequest @relation(fields: [request_id], references: [id], onDelete: Cascade)\n  signer  Signer?          @relation(fields: [signer_id], references: [id], onDelete: SetNull)\n\n  @@unique([provider, provider_event_id])\n  @@index([request_id, occurred_at])\n  @@map(\"signature_events\")\n}\n\n// --- Obligations & termination ----------------------------------------------------\n\n/// 04 §49–50, §75 — operational obligations linked to a contract section; execution may create a\n/// Task (06) rather than duplicating task functionality.\nmodel ContractObligation {\n  id                        String                   @id @default(uuid())\n  contract_id               String\n  section_id                String?\n  type                      ContractObligationType   @default(OTHER)\n  title                     String\n  description               String?\n  /// Responsible side: a party of the contract and/or an internal Member.\n  responsible_party_id      String?\n  responsible_membership_id String?\n  due_date                  DateTime?                @db.Date\n  /// none | weekly | monthly | quarterly | annual\n  frequency                 String?\n  status                    ContractObligationStatus @default(OPEN)\n  reminder_days_before      Int?\n  /// Related Project (05) and Task (06); ids only.\n  project_id                String?\n  task_id                   String?\n  /// AI extraction provenance (04 §75).\n  is_ai_extracted           Boolean                  @default(false)\n  extraction_confidence     Decimal?                 @db.Decimal(5, 4)\n  review_state              ExtractionReviewState?\n  fulfilled_at              DateTime?\n  created_at                DateTime                 @default(now())\n  updated_at                DateTime                 @updatedAt\n\n  contract Contract         @relation(fields: [contract_id], references: [id], onDelete: Cascade)\n  section  ContractSection? @relation(fields: [section_id], references: [id], onDelete: SetNull)\n  task     Task?            @relation(fields: [task_id], references: [id], onDelete: SetNull)\n\n  @@index([contract_id, status])\n  @@index([due_date])\n  @@map(\"contract_obligations\")\n}\n\n/// 04 §53 — termination record. Never alters the signed document.\nmodel ContractTermination {\n  contract_id         String                  @id\n  type                ContractTerminationType @default(FOR_CONVENIENCE)\n  reason              String?\n  requesting_party_id String?\n  notice_date         DateTime?               @db.Date\n  effective_date      DateTime                @db.Date\n  approved_by_user_id String?\n  approved_at         DateTime?\n  /// Supporting document (17); id only.\n  document_id         String?\n  notes               String?\n  created_by_user_id  String?\n  created_at          DateTime                @default(now())\n\n  contract Contract @relation(fields: [contract_id], references: [id], onDelete: Cascade)\n\n  @@map(\"contract_terminations\")\n}\n\n// =====================================================================\n// 05 Project Management — docs/features/05-project-management.md (LOG-405)\n// Owns: project types/statuses/templates, Project, membership and roles, branches, stakeholders,\n// objectives, workstreams, milestones, deliverables, acceptance criteria, dependencies, risks,\n// issues/blockers, decisions, status updates, project change requests, gates, reviews, allocation,\n// checklists, escalations, handovers, closeout, relationships, external references.\n// Does not own: Tasks (06), time entries (18), documents (17), messages (12), tickets (13),\n// invoices/expenses (08/09), calendar events (19), employees (10). Referenced by id only.\n// Project notes use the polymorphic notes table (crm_notes, entity_type PROJECT).\n// Project activity and change history (05 §42–43) are written to audit_events.\n// =====================================================================\n\n/// 05 §4 — semantic category of a configurable status.\nenum ProjectStatusCategory {\n  DRAFT\n  PLANNED\n  NOT_STARTED\n  IN_PROGRESS\n  ON_HOLD\n  BLOCKED\n  READY_FOR_COMPLETION\n  COMPLETED\n  CANCELLED\n  ARCHIVED\n}\n\n/// 05 §13\nenum ProjectHealth {\n  HEALTHY\n  AT_RISK\n  BLOCKED\n  CRITICAL\n  UNKNOWN\n}\n\n/// 05 §13–14 — how health / progress are determined.\nenum CalculationMode {\n  MANUAL\n  AUTOMATIC\n  HYBRID\n}\n\n/// 05 §80\nenum ProjectPriority {\n  CRITICAL\n  HIGH\n  MEDIUM\n  LOW\n}\n\n/// 05 §60, §111 — customer exposure of the project.\nenum ProjectVisibility {\n  INTERNAL\n  CUSTOMER_VISIBLE\n}\n\n/// 05 §19–20\nenum ProjectItemStatus {\n  PLANNED\n  IN_PROGRESS\n  AT_RISK\n  COMPLETED\n  CANCELLED\n}\n\n/// 05 §18 — deliverable lifecycle including customer acceptance (05 §47, 07 §7).\nenum DeliverableStatus {\n  PLANNED\n  IN_PROGRESS\n  READY_FOR_REVIEW\n  SUBMITTED\n  CHANGES_REQUESTED\n  ACCEPTED\n  REJECTED\n  CANCELLED\n}\n\n/// 05 §47\nenum AcceptanceStatus {\n  PENDING\n  PASSED\n  FAILED\n  WAIVED\n}\n\n/// 05 §21, §27–28 — what a dependency endpoint is.\nenum DependencyItemType {\n  PROJECT\n  WORKSTREAM\n  MILESTONE\n  DELIVERABLE\n  TASK\n  EXTERNAL\n}\n\n/// 05 §27\nenum DependencyType {\n  FINISH_TO_START\n  START_TO_START\n  FINISH_TO_FINISH\n  START_TO_FINISH\n  BLOCKS\n  RELATED\n}\n\nenum DependencyStatus {\n  OPEN\n  RESOLVED\n  CANCELLED\n}\n\n/// 05 §29\nenum RiskStatus {\n  OPEN\n  MONITORING\n  MITIGATED\n  ACCEPTED\n  RESOLVED\n  CLOSED\n}\n\n/// 05 §30–31 — a Project Issue is a delivery problem; a Blocker is an issue preventing progress.\nenum ProjectIssueKind {\n  ISSUE\n  BLOCKER\n}\n\nenum ProjectIssueStatus {\n  OPEN\n  IN_PROGRESS\n  RESOLVED\n  CLOSED\n  CANCELLED\n}\n\nenum Severity {\n  LOW\n  MEDIUM\n  HIGH\n  CRITICAL\n}\n\n/// 05 §45 — Project Change Request status (not a Contract Change Request, 04 §26).\nenum ProjectChangeRequestStatus {\n  REQUESTED\n  UNDER_REVIEW\n  ESTIMATING\n  AWAITING_APPROVAL\n  APPROVED\n  REJECTED\n  SCHEDULED\n  IMPLEMENTED\n  CANCELLED\n}\n\n/// 05 §46, §93 — approval and quality gates share one model.\nenum ProjectGateKind {\n  APPROVAL\n  QUALITY\n}\n\nenum ProjectGateStatus {\n  PENDING\n  PASSED\n  FAILED\n  WAIVED\n}\n\n/// 05 §48–49\nenum ProjectReviewType {\n  KICKOFF\n  MILESTONE\n  DELIVERY\n  QUALITY\n  CUSTOMER\n  POST_PROJECT\n  RETROSPECTIVE\n}\n\n/// 05 §105\nenum ProjectRelationType {\n  RELATED\n  DEPENDENCY\n  REPLACEMENT\n  FOLLOW_UP\n  MAINTENANCE_FOR\n  CONTINUATION_OF\n}\n\n/// 05 §101\nenum EscalationStatus {\n  OPEN\n  ACKNOWLEDGED\n  RESOLVED\n  CLOSED\n}\n\n/// 05 §72, §102\nenum HandoverStatus {\n  PLANNED\n  IN_PROGRESS\n  COMPLETED\n  CANCELLED\n}\n\n// --- Configuration ----------------------------------------------------------------\n\n/// 05 §2 — organization-defined project types with defaults.\nmodel ProjectType {\n  id                      String    @id @default(uuid())\n  organization_id         String\n  name                    String\n  slug                    String\n  description             String?\n  default_template_id     String?\n  /// Workspace sections enabled by default (05 §11).\n  enabled_sections        String[]  @default([])\n  required_fields         String[]  @default([])\n  /// Health rules for AUTOMATIC/HYBRID mode (05 §13).\n  health_rules            Json?\n  /// Completion checklist requirements (05 §71).\n  completion_requirements Json?\n  is_default              Boolean   @default(false)\n  sort_order              Int       @default(0)\n  archived_at             DateTime?\n  created_at              DateTime  @default(now())\n  updated_at              DateTime  @updatedAt\n\n  organization     Organization      @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  default_template ProjectTemplate?  @relation(\"ProjectTypeDefaultTemplate\", fields: [default_template_id], references: [id], onDelete: SetNull)\n  templates        ProjectTemplate[] @relation(\"ProjectTemplateType\")\n  projects         Project[]\n\n  @@unique([organization_id, slug])\n  @@map(\"project_types\")\n}\n\n/// 05 §4 — configurable lifecycle statuses with allowed transitions.\nmodel ProjectStatus {\n  id                  String                @id @default(uuid())\n  organization_id     String\n  name                String\n  slug                String\n  category            ProjectStatusCategory\n  color               String?\n  sort_order          Int                   @default(0)\n  is_default          Boolean               @default(false)\n  /// Slugs of statuses this one may transition to; null = any.\n  allowed_transitions String[]              @default([])\n  archived_at         DateTime?\n  created_at          DateTime              @default(now())\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  projects     Project[]\n\n  @@unique([organization_id, slug])\n  @@map(\"project_statuses\")\n}\n\n/// 05 §36–37 — templates with versions; updating a template never modifies existing projects.\nmodel ProjectTemplate {\n  id                 String    @id @default(uuid())\n  organization_id    String\n  type_id            String?\n  name               String\n  slug               String\n  description        String?\n  current_version_id String?   @unique\n  is_active          Boolean   @default(true)\n  deprecated_at      DateTime?\n  created_by_user_id String?\n  created_at         DateTime  @default(now())\n  updated_at         DateTime  @updatedAt\n\n  organization      Organization             @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  type              ProjectType?             @relation(\"ProjectTemplateType\", fields: [type_id], references: [id], onDelete: SetNull)\n  current_version   ProjectTemplateVersion?  @relation(\"ProjectTemplateCurrentVersion\", fields: [current_version_id], references: [id], onDelete: SetNull)\n  versions          ProjectTemplateVersion[]\n  default_for_types ProjectType[]            @relation(\"ProjectTypeDefaultTemplate\")\n  projects          Project[]\n\n  @@unique([organization_id, slug])\n  @@map(\"project_templates\")\n}\n\n/// 05 §37 — immutable template content: statuses, milestones, workstreams, task structures,\n/// dependencies, roles, required fields, standard documents, checklists, health rules, views.\nmodel ProjectTemplateVersion {\n  id                 String   @id @default(uuid())\n  template_id        String\n  version_number     Int\n  change_summary     String?\n  structure          Json\n  created_by_user_id String?\n  created_at         DateTime @default(now())\n\n  template   ProjectTemplate  @relation(fields: [template_id], references: [id], onDelete: Cascade)\n  current_of ProjectTemplate? @relation(\"ProjectTemplateCurrentVersion\")\n  projects   Project[]\n\n  @@unique([template_id, version_number])\n  @@map(\"project_template_versions\")\n}\n\n// --- Project ------------------------------------------------------------------------\n\n/// 05 §3, §5–7, §12–15, §80, §106–107, §117 — the project record.\nmodel Project {\n  id                  String            @id @default(uuid())\n  organization_id     String\n  /// Primary branch (01 §32). Participating branches in ProjectBranch.\n  branch_id           String?\n  parent_project_id   String?\n  name                String\n  /// Optional human project code (05 §6, §114); stable id is `id`.\n  code                String?\n  slug                String\n  description         String?\n  type_id             String?\n  status_id           String?\n  health              ProjectHealth     @default(UNKNOWN)\n  health_mode         CalculationMode   @default(HYBRID)\n  health_reason       String?\n  progress_percent    Int               @default(0)\n  progress_mode       CalculationMode   @default(AUTOMATIC)\n  priority            ProjectPriority   @default(MEDIUM)\n  visibility          ProjectVisibility @default(INTERNAL)\n  /// Customer (CRM Company, 02). Optional: internal projects have none (05 §3, §56).\n  company_id          String?\n  owner_membership_id String?\n  team_id             String?\n  template_id         String?\n  template_version_id String?\n  /// Source proposal and exact version (03), set when created from an accepted proposal (05 §57).\n  proposal_id         String?\n  proposal_version_id String?\n  // 05 §15 — dates.\n  planned_start       DateTime?         @db.Date\n  actual_start        DateTime?         @db.Date\n  target_completion   DateTime?         @db.Date\n  actual_completion   DateTime?         @db.Date\n  review_date         DateTime?         @db.Date\n  internal_deadline   DateTime?         @db.Date\n  customer_deadline   DateTime?         @db.Date\n  /// 05 §51 — planned budget context; actual financials live in 08/09.\n  budget_hours        Decimal?          @db.Decimal(12, 2)\n  budget_amount       Decimal?          @db.Decimal(18, 2)\n  currency            String?\n  icon                String?\n  color               String?\n  /// Messaging project channel (12 §26); id only.\n  channel_id          String?\n  /// Business Docs runbook page (15 §4); id only.\n  runbook_page_id     String?\n  completed_at        DateTime?\n  cancelled_at        DateTime?\n  archived_at         DateTime?\n  reopened_at         DateTime?\n  created_by_user_id  String?\n  created_at          DateTime          @default(now())\n  updated_at          DateTime          @updatedAt\n\n  organization     Organization            @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  branch           Branch?                 @relation(fields: [branch_id], references: [id], onDelete: SetNull)\n  parent           Project?                @relation(\"ProjectHierarchy\", fields: [parent_project_id], references: [id], onDelete: SetNull)\n  children         Project[]               @relation(\"ProjectHierarchy\")\n  type             ProjectType?            @relation(fields: [type_id], references: [id], onDelete: SetNull)\n  status           ProjectStatus?          @relation(fields: [status_id], references: [id], onDelete: SetNull)\n  company          CrmCompany?             @relation(fields: [company_id], references: [id], onDelete: SetNull)\n  owner            Membership?             @relation(\"ProjectOwner\", fields: [owner_membership_id], references: [id], onDelete: SetNull)\n  team             Team?                   @relation(fields: [team_id], references: [id], onDelete: SetNull)\n  template         ProjectTemplate?        @relation(fields: [template_id], references: [id], onDelete: SetNull)\n  template_version ProjectTemplateVersion? @relation(fields: [template_version_id], references: [id], onDelete: SetNull)\n  proposal         Proposal?               @relation(\"ProjectSourceProposal\", fields: [proposal_id], references: [id], onDelete: SetNull)\n  proposal_version ProposalVersion?        @relation(\"ProjectSourceProposalVersion\", fields: [proposal_version_id], references: [id], onDelete: SetNull)\n\n  branches                 ProjectBranch[]\n  members                  ProjectMember[]\n  stakeholders             ProjectStakeholder[]\n  objectives               ProjectObjective[]\n  workstreams              ProjectWorkstream[]\n  milestones               ProjectMilestone[]\n  deliverables             ProjectDeliverable[]\n  dependencies             ProjectDependency[]\n  risks                    ProjectRisk[]\n  issues                   ProjectIssue[]\n  decisions                ProjectDecision[]\n  status_updates           ProjectStatusUpdate[]\n  change_requests          ProjectChangeRequest[]\n  gates                    ProjectGate[]\n  reviews                  ProjectReview[]\n  allocations              ProjectAllocation[]\n  checklists               ProjectChecklist[]\n  escalations              ProjectEscalation[]\n  handovers                ProjectHandover[]\n  closeout                 ProjectCloseout?\n  relations_from           ProjectRelation[]          @relation(\"ProjectRelationSource\")\n  relations_to             ProjectRelation[]          @relation(\"ProjectRelationTarget\")\n  external_refs            ProjectExternalReference[]\n  contracts                ContractProject[]\n  deals                    CrmDeal[]                  @relation(\"CrmDealProject\")\n  converted_from_proposals Proposal[]                 @relation(\"ProposalConvertedProject\")\n  tasks                    Task[]\n  cycles                   Cycle[]\n  releases                 Release[]\n\n  @@unique([organization_id, slug])\n  @@unique([organization_id, code])\n  @@index([organization_id, status_id])\n  @@index([organization_id, health])\n  @@index([company_id])\n  @@index([owner_membership_id])\n  @@index([parent_project_id])\n  @@index([target_completion])\n  @@map(\"projects\")\n}\n\n/// 01 §32–33 — participating branches of a multi-branch project (primary is projects.branch_id).\nmodel ProjectBranch {\n  project_id String\n  branch_id  String\n  created_at DateTime @default(now())\n\n  project Project @relation(fields: [project_id], references: [id], onDelete: Cascade)\n  branch  Branch  @relation(fields: [branch_id], references: [id], onDelete: Cascade)\n\n  @@id([project_id, branch_id])\n  @@index([branch_id])\n  @@map(\"project_branches\")\n}\n\n/// 05 §8–9 — internal participants. role_id is a Role of type PROJECT (01 §45).\nmodel ProjectMember {\n  id                 String    @id @default(uuid())\n  project_id         String\n  membership_id      String\n  role_id            String?\n  /// Free-text role label when no Role is used (Developer, Designer, QA, …).\n  role_label         String?\n  allocation_percent Int?\n  is_active          Boolean   @default(true)\n  joined_at          DateTime  @default(now())\n  left_at            DateTime?\n  created_at         DateTime  @default(now())\n\n  project    Project    @relation(fields: [project_id], references: [id], onDelete: Cascade)\n  membership Membership @relation(fields: [membership_id], references: [id], onDelete: Cascade)\n  role       Role?      @relation(fields: [role_id], references: [id], onDelete: SetNull)\n\n  @@unique([project_id, membership_id])\n  @@index([membership_id, is_active])\n  @@map(\"project_members\")\n}\n\n/// 05 §53 — external stakeholders: customer contacts (02), vendors, partners, consultants.\nmodel ProjectStakeholder {\n  id                 String   @id @default(uuid())\n  project_id         String\n  contact_id         String?\n  name               String\n  organization_name  String?\n  email              String?\n  role               String?\n  responsibility     String?\n  /// Whether the stakeholder sees the project in the Customer Portal (via 01 §79 identity).\n  portal_visible     Boolean  @default(false)\n  decision_authority Boolean  @default(false)\n  created_at         DateTime @default(now())\n\n  project Project     @relation(fields: [project_id], references: [id], onDelete: Cascade)\n  contact CrmContact? @relation(fields: [contact_id], references: [id], onDelete: SetNull)\n\n  @@index([project_id])\n  @@map(\"project_stakeholders\")\n}\n\n// --- Planning ----------------------------------------------------------------------\n\n/// 05 §17\nmodel ProjectObjective {\n  id                  String            @id @default(uuid())\n  project_id          String\n  name                String\n  description         String?\n  owner_membership_id String?\n  target_date         DateTime?         @db.Date\n  success_criteria    String?\n  status              ProjectItemStatus @default(PLANNED)\n  progress_percent    Int               @default(0)\n  sort_order          Int               @default(0)\n  created_at          DateTime          @default(now())\n  updated_at          DateTime          @updatedAt\n\n  project    Project            @relation(fields: [project_id], references: [id], onDelete: Cascade)\n  milestones ProjectMilestone[]\n\n  @@index([project_id])\n  @@map(\"project_objectives\")\n}\n\n/// 05 §19\nmodel ProjectWorkstream {\n  id                  String            @id @default(uuid())\n  project_id          String\n  name                String\n  description         String?\n  owner_membership_id String?\n  status              ProjectItemStatus @default(PLANNED)\n  progress_percent    Int               @default(0)\n  planned_start       DateTime?         @db.Date\n  planned_end         DateTime?         @db.Date\n  actual_start        DateTime?         @db.Date\n  actual_end          DateTime?         @db.Date\n  color               String?\n  sort_order          Int               @default(0)\n  archived_at         DateTime?\n  created_at          DateTime          @default(now())\n  updated_at          DateTime          @updatedAt\n\n  project      Project              @relation(fields: [project_id], references: [id], onDelete: Cascade)\n  milestones   ProjectMilestone[]\n  deliverables ProjectDeliverable[]\n  allocations  ProjectAllocation[]\n  tasks        Task[]\n\n  @@index([project_id])\n  @@map(\"project_workstreams\")\n}\n\n/// 05 §20 — major checkpoints. Task links come from Task Management (06).\nmodel ProjectMilestone {\n  id                     String            @id @default(uuid())\n  project_id             String\n  workstream_id          String?\n  objective_id           String?\n  name                   String\n  description            String?\n  owner_membership_id    String?\n  status                 ProjectItemStatus @default(PLANNED)\n  planned_date           DateTime?         @db.Date\n  actual_date            DateTime?         @db.Date\n  progress_percent       Int               @default(0)\n  /// Shown in the Customer Portal (05 §60) and projected onto the Calendar (19).\n  customer_visible       Boolean           @default(false)\n  /// Triggers milestone billing in 08 when completed.\n  is_billing_milestone   Boolean           @default(false)\n  /// Proposal milestone this was created from (03), stored as the proposal's milestone key.\n  proposal_milestone_key String?\n  notes                  String?\n  sort_order             Int               @default(0)\n  completed_at           DateTime?\n  created_at             DateTime          @default(now())\n  updated_at             DateTime          @updatedAt\n\n  project             Project                      @relation(fields: [project_id], references: [id], onDelete: Cascade)\n  workstream          ProjectWorkstream?           @relation(fields: [workstream_id], references: [id], onDelete: SetNull)\n  objective           ProjectObjective?            @relation(fields: [objective_id], references: [id], onDelete: SetNull)\n  deliverables        ProjectDeliverable[]\n  acceptance_criteria ProjectAcceptanceCriterion[]\n  gates               ProjectGate[]\n  allocations         ProjectAllocation[]\n  tasks               Task[]\n\n  @@index([project_id, planned_date])\n  @@index([workstream_id])\n  @@map(\"project_milestones\")\n}\n\n/// 05 §18 — tangible outputs. Files are Documents (17); commercial scope stays in 03/04.\nmodel ProjectDeliverable {\n  id                  String            @id @default(uuid())\n  project_id          String\n  milestone_id        String?\n  workstream_id       String?\n  name                String\n  description         String?\n  owner_membership_id String?\n  status              DeliverableStatus @default(PLANNED)\n  due_date            DateTime?         @db.Date\n  customer_visible    Boolean           @default(false)\n  /// Document ids (17) delivered.\n  document_ids        String[]          @default([])\n  /// Proposal line item / section reference (03) for commercial scope traceability.\n  proposal_reference  String?\n  submitted_at        DateTime?\n  accepted_at         DateTime?\n  /// Customer acceptance evidence: portal user id, contact id, comment (07 §7).\n  acceptance_record   Json?\n  sort_order          Int               @default(0)\n  created_at          DateTime          @default(now())\n  updated_at          DateTime          @updatedAt\n\n  project             Project                      @relation(fields: [project_id], references: [id], onDelete: Cascade)\n  milestone           ProjectMilestone?            @relation(fields: [milestone_id], references: [id], onDelete: SetNull)\n  workstream          ProjectWorkstream?           @relation(fields: [workstream_id], references: [id], onDelete: SetNull)\n  acceptance_criteria ProjectAcceptanceCriterion[]\n\n  @@index([project_id, status])\n  @@index([milestone_id])\n  @@map(\"project_deliverables\")\n}\n\n/// 05 §47 — acceptance criteria on a deliverable or milestone. Contractual acceptance terms are 04.\nmodel ProjectAcceptanceCriterion {\n  id                     String           @id @default(uuid())\n  deliverable_id         String?\n  milestone_id           String?\n  requirement            String\n  expected_outcome       String?\n  verification_method    String?\n  status                 AcceptanceStatus @default(PENDING)\n  reviewer_membership_id String?\n  reviewed_at            DateTime?\n  sort_order             Int              @default(0)\n\n  deliverable ProjectDeliverable? @relation(fields: [deliverable_id], references: [id], onDelete: Cascade)\n  milestone   ProjectMilestone?   @relation(fields: [milestone_id], references: [id], onDelete: Cascade)\n\n  @@index([deliverable_id])\n  @@index([milestone_id])\n  @@map(\"project_acceptance_criteria\")\n}\n\n/// 05 §21, §27–28 — dependencies between tasks, milestones, workstreams, deliverables and projects.\n/// Endpoints are typed ids so Task (06) endpoints work without a FK.\nmodel ProjectDependency {\n  id                  String             @id @default(uuid())\n  project_id          String\n  source_type         DependencyItemType\n  source_id           String\n  target_type         DependencyItemType\n  target_id           String\n  type                DependencyType     @default(FINISH_TO_START)\n  status              DependencyStatus   @default(OPEN)\n  owner_membership_id String?\n  expected_resolution DateTime?          @db.Date\n  lag_days            Int?\n  notes               String?\n  resolved_at         DateTime?\n  created_at          DateTime           @default(now())\n\n  project Project @relation(fields: [project_id], references: [id], onDelete: Cascade)\n\n  @@index([project_id, status])\n  @@index([source_type, source_id])\n  @@index([target_type, target_id])\n  @@map(\"project_dependencies\")\n}\n\n// --- Delivery visibility -------------------------------------------------------------\n\n/// 05 §29\nmodel ProjectRisk {\n  id                  String     @id @default(uuid())\n  project_id          String\n  title               String\n  description         String?\n  category            String?\n  /// 1–5 scales; severity derived or set.\n  probability         Int?\n  impact              Int?\n  severity            Severity   @default(MEDIUM)\n  status              RiskStatus @default(OPEN)\n  owner_membership_id String?\n  mitigation          String?\n  contingency         String?\n  due_date            DateTime?  @db.Date\n  milestone_id        String?\n  task_id             String?\n  resolved_at         DateTime?\n  created_at          DateTime   @default(now())\n  updated_at          DateTime   @updatedAt\n\n  project Project @relation(fields: [project_id], references: [id], onDelete: Cascade)\n\n  @@index([project_id, status])\n  @@map(\"project_risks\")\n}\n\n/// 05 §30–31 — Project Issues and Blockers (kind). Distinct from Support tickets (13) and Tasks (06).\nmodel ProjectIssue {\n  id                  String              @id @default(uuid())\n  project_id          String\n  kind                ProjectIssueKind    @default(ISSUE)\n  title               String\n  description         String?\n  severity            Severity            @default(MEDIUM)\n  priority            ProjectPriority     @default(MEDIUM)\n  status              ProjectIssueStatus  @default(OPEN)\n  owner_membership_id String?\n  /// For blockers: what is blocked (typed id).\n  blocked_item_type   DependencyItemType?\n  blocked_item_id     String?\n  milestone_id        String?\n  task_id             String?\n  dependency_id       String?\n  /// Linked support ticket (13) when the issue originated from support; id only.\n  ticket_id           String?\n  identified_at       DateTime            @default(now())\n  target_resolution   DateTime?           @db.Date\n  resolution          String?\n  resolved_at         DateTime?\n  created_at          DateTime            @default(now())\n  updated_at          DateTime            @updatedAt\n\n  project Project @relation(fields: [project_id], references: [id], onDelete: Cascade)\n  task    Task?   @relation(fields: [task_id], references: [id], onDelete: SetNull)\n\n  @@index([project_id, kind, status])\n  @@map(\"project_issues\")\n}\n\n/// 05 §32 — decision records.\nmodel ProjectDecision {\n  id                           String   @id @default(uuid())\n  project_id                   String\n  title                        String\n  description                  String?\n  decided_at                   DateTime @default(now())\n  decision_maker_membership_id String?\n  /// Membership ids.\n  participants                 String[] @default([])\n  alternatives_considered      String?\n  selected_option              String?\n  reason                       String?\n  consequences                 String?\n  milestone_id                 String?\n  task_id                      String?\n  document_id                  String?\n  /// Source message permalink (12 §63) when converted from a conversation.\n  source_message_id            String?\n  created_at                   DateTime @default(now())\n\n  project Project @relation(fields: [project_id], references: [id], onDelete: Cascade)\n\n  @@index([project_id, decided_at])\n  @@map(\"project_decisions\")\n}\n\n/// 05 §39 — structured status updates; customer-visible ones appear in the portal (07 §4).\nmodel ProjectStatusUpdate {\n  id                   String         @id @default(uuid())\n  project_id           String\n  period_start         DateTime?      @db.Date\n  period_end           DateTime?      @db.Date\n  summary              String\n  completed_work       String?\n  current_work         String?\n  upcoming_work        String?\n  progress_percent     Int?\n  health               ProjectHealth?\n  risks_summary        String?\n  blockers_summary     String?\n  decisions_summary    String?\n  required_actions     String?\n  author_membership_id String?\n  customer_visible     Boolean        @default(false)\n  published_at         DateTime?\n  is_ai_generated      Boolean        @default(false)\n  created_at           DateTime       @default(now())\n  updated_at           DateTime       @updatedAt\n\n  project Project @relation(fields: [project_id], references: [id], onDelete: Cascade)\n\n  @@index([project_id, published_at])\n  @@map(\"project_status_updates\")\n}\n\n/// 05 §45 — Project Change Request: changes affecting delivery. Commercial approval stays with\n/// 03/04 (proposal_id, contract_id); a Contract Change Request (04 §26) may be linked.\nmodel ProjectChangeRequest {\n  id                           String                     @id @default(uuid())\n  project_id                   String\n  number                       Int\n  title                        String\n  description                  String?\n  requester_membership_id      String?\n  requester_contact_id         String?\n  requested_at                 DateTime                   @default(now())\n  priority                     ProjectPriority            @default(MEDIUM)\n  status                       ProjectChangeRequestStatus @default(REQUESTED)\n  scope_impact                 String?\n  timeline_impact_days         Int?\n  resource_impact              String?\n  cost_impact_amount           Decimal?                   @db.Decimal(18, 2)\n  currency                     String?\n  customer_visible             Boolean                    @default(false)\n  approved_by_membership_id    String?\n  approved_by_customer_user_id String?\n  approved_at                  DateTime?\n  rejected_reason              String?\n  deliverable_id               String?\n  task_id                      String?\n  /// Commercial links (03, 04) and the contract change request this originated (04 §26, §43).\n  proposal_id                  String?\n  contract_id                  String?\n  contract_change_request_id   String?\n  implemented_at               DateTime?\n  created_at                   DateTime                   @default(now())\n  updated_at                   DateTime                   @updatedAt\n\n  project Project @relation(fields: [project_id], references: [id], onDelete: Cascade)\n  task    Task?   @relation(fields: [task_id], references: [id], onDelete: SetNull)\n\n  @@unique([project_id, number])\n  @@index([project_id, status])\n  @@map(\"project_change_requests\")\n}\n\n/// 05 §46, §93 — approval gates (requirements, design, development, QA, security, customer\n/// acceptance, launch, handover) and quality gates (code review, QA, security review, documentation).\nmodel ProjectGate {\n  id                        String            @id @default(uuid())\n  project_id                String\n  kind                      ProjectGateKind   @default(APPROVAL)\n  name                      String\n  description               String?\n  milestone_id              String?\n  approver_membership_id    String?\n  /// Customer approval gates are decided by a Customer Portal User (01 §79); id only.\n  customer_approver_user_id String?\n  status                    ProjectGateStatus @default(PENDING)\n  blocks_completion         Boolean           @default(false)\n  decision_comment          String?\n  decided_at                DateTime?\n  sort_order                Int               @default(0)\n  created_at                DateTime          @default(now())\n  updated_at                DateTime          @updatedAt\n\n  project   Project           @relation(fields: [project_id], references: [id], onDelete: Cascade)\n  milestone ProjectMilestone? @relation(fields: [milestone_id], references: [id], onDelete: SetNull)\n  approver  Membership?       @relation(\"ProjectGateApprover\", fields: [approver_membership_id], references: [id], onDelete: SetNull)\n\n  @@index([project_id, status])\n  @@map(\"project_gates\")\n}\n\n/// 05 §48–49 — structured reviews and retrospectives. Actions may create Tasks (06).\nmodel ProjectReview {\n  id                        String            @id @default(uuid())\n  project_id                String\n  type                      ProjectReviewType\n  title                     String\n  held_at                   DateTime?\n  facilitator_membership_id String?\n  /// Membership ids.\n  participants              String[]          @default([])\n  findings                  String?\n  decisions                 String?\n  /// Retrospective fields (05 §49).\n  went_well                 String?\n  went_wrong                String?\n  root_causes               String?\n  lessons                   String?\n  /// Actions: [{ title, owner_membership_id, due_date, task_id? }].\n  actions                   Json?\n  milestone_id              String?\n  created_at                DateTime          @default(now())\n  updated_at                DateTime          @updatedAt\n\n  project Project @relation(fields: [project_id], references: [id], onDelete: Cascade)\n\n  @@index([project_id, type])\n  @@map(\"project_reviews\")\n}\n\n// --- Resources ------------------------------------------------------------------------\n\n/// 05 §51 — planned allocation (the plan). Availability is 10; actuals are 18.\nmodel ProjectAllocation {\n  id                 String    @id @default(uuid())\n  project_id         String\n  membership_id      String?\n  team_id            String?\n  role_label         String?\n  workstream_id      String?\n  milestone_id       String?\n  planned_hours      Decimal?  @db.Decimal(10, 2)\n  allocation_percent Int?\n  start_date         DateTime? @db.Date\n  end_date           DateTime? @db.Date\n  notes              String?\n  created_at         DateTime  @default(now())\n  updated_at         DateTime  @updatedAt\n\n  project    Project            @relation(fields: [project_id], references: [id], onDelete: Cascade)\n  membership Membership?        @relation(fields: [membership_id], references: [id], onDelete: Cascade)\n  team       Team?              @relation(fields: [team_id], references: [id], onDelete: Cascade)\n  workstream ProjectWorkstream? @relation(fields: [workstream_id], references: [id], onDelete: SetNull)\n  milestone  ProjectMilestone?  @relation(fields: [milestone_id], references: [id], onDelete: SetNull)\n\n  @@index([project_id])\n  @@index([membership_id, start_date, end_date])\n  @@map(\"project_allocations\")\n}\n\n/// 05 §92 — reusable checklists (kickoff, discovery, development, QA, launch, handover, closeout).\nmodel ProjectChecklist {\n  id         String   @id @default(uuid())\n  project_id String\n  name       String\n  /// kickoff | discovery | development | qa | launch | handover | closeout | custom\n  phase      String?\n  sort_order Int      @default(0)\n  created_at DateTime @default(now())\n\n  project Project                @relation(fields: [project_id], references: [id], onDelete: Cascade)\n  items   ProjectChecklistItem[]\n\n  @@index([project_id])\n  @@map(\"project_checklists\")\n}\n\nmodel ProjectChecklistItem {\n  id                         String    @id @default(uuid())\n  checklist_id               String\n  title                      String\n  is_required                Boolean   @default(false)\n  is_completed               Boolean   @default(false)\n  completed_by_membership_id String?\n  completed_at               DateTime?\n  /// Task created from this item (06).\n  task_id                    String?\n  sort_order                 Int       @default(0)\n\n  checklist ProjectChecklist @relation(fields: [checklist_id], references: [id], onDelete: Cascade)\n  task      Task?            @relation(fields: [task_id], references: [id], onDelete: SetNull)\n\n  @@index([checklist_id])\n  @@map(\"project_checklist_items\")\n}\n\n// --- Governance & closeout -------------------------------------------------------------\n\n/// 05 §101\nmodel ProjectEscalation {\n  id                         String           @id @default(uuid())\n  project_id                 String\n  issue_summary              String\n  /// blocker | delay | budget | scope | customer | resources | contract\n  category                   String?\n  severity                   Severity         @default(HIGH)\n  status                     EscalationStatus @default(OPEN)\n  owner_membership_id        String?\n  escalated_to_membership_id String?\n  escalated_at               DateTime         @default(now())\n  action_taken               String?\n  resolution                 String?\n  resolved_at                DateTime?\n  issue_id                   String?\n  created_at                 DateTime         @default(now())\n\n  project Project @relation(fields: [project_id], references: [id], onDelete: Cascade)\n\n  @@index([project_id, status])\n  @@map(\"project_escalations\")\n}\n\n/// 05 §72, §102 — handovers between teams or to maintenance / support / customer success.\nmodel ProjectHandover {\n  id                        String         @id @default(uuid())\n  project_id                String\n  /// sales_to_delivery | delivery_to_support | development_to_qa | qa_to_customer | project_to_maintenance | custom\n  type                      String\n  from_team_id              String?\n  to_team_id                String?\n  new_owner_membership_id   String?\n  status                    HandoverStatus @default(PLANNED)\n  scheduled_at              DateTime?\n  completed_at              DateTime?\n  /// Checklist, documentation ids (17), open items, support references, contacts, notes.\n  details                   Json?\n  accepted_by_membership_id String?\n  accepted_at               DateTime?\n  created_at                DateTime       @default(now())\n  updated_at                DateTime       @updatedAt\n\n  project Project @relation(fields: [project_id], references: [id], onDelete: Cascade)\n\n  @@index([project_id, status])\n  @@map(\"project_handovers\")\n}\n\n/// 05 §71, §103 — completion checklist state and closeout record.\nmodel ProjectCloseout {\n  project_id                      String    @id\n  /// Completion requirement results (05 §71): [{ key, label, required, satisfied, note }].\n  completion_checklist            Json?\n  final_status_summary            String?\n  outstanding_items               String?\n  lessons_learned                 String?\n  customer_outcome                String?\n  /// Financial review reference (08/09); id only.\n  financial_review_ref            String?\n  documentation_document_ids      String[]  @default([])\n  customer_acceptance_recorded_at DateTime?\n  closed_by_membership_id         String?\n  closed_at                       DateTime?\n  updated_at                      DateTime  @updatedAt\n\n  project Project @relation(fields: [project_id], references: [id], onDelete: Cascade)\n\n  @@map(\"project_closeouts\")\n}\n\n/// 05 §105 — non-hierarchical relationships between projects (parent/child uses parent_project_id).\nmodel ProjectRelation {\n  id                String              @id @default(uuid())\n  source_project_id String\n  target_project_id String\n  type              ProjectRelationType @default(RELATED)\n  notes             String?\n  created_at        DateTime            @default(now())\n\n  source Project @relation(\"ProjectRelationSource\", fields: [source_project_id], references: [id], onDelete: Cascade)\n  target Project @relation(\"ProjectRelationTarget\", fields: [target_project_id], references: [id], onDelete: Cascade)\n\n  @@unique([source_project_id, target_project_id, type])\n  @@index([target_project_id])\n  @@map(\"project_relations\")\n}\n\n/// 05 §86 — references to external systems (GitHub, GitLab, Jira, Linear, deployment, cloud, docs).\nmodel ProjectExternalReference {\n  id          String   @id @default(uuid())\n  project_id  String\n  /// github | gitlab | jira | linear | notion | google_drive | microsoft_365 | deployment | cloud | other\n  system      String\n  label       String?\n  external_id String?\n  url         String?\n  metadata    Json?\n  created_at  DateTime @default(now())\n\n  project Project @relation(fields: [project_id], references: [id], onDelete: Cascade)\n\n  @@index([project_id, system])\n  @@map(\"project_external_references\")\n}\n\n// =====================================================================\n// 06 Task Management — docs/features/06-task-management.md (LOG-102)\n// Owns: the only Task entity, task statuses/workflows, task types, labels, cycles, dependencies,\n// assignees, watchers, checklists, comments, attachments, polymorphic links to other records,\n// Releases and deployments. \"Issue\" in the UI means Task.\n// Does not own: Projects/Milestones/Workstreams (05), time entries (18), documents (17),\n// conversations (12), tickets (13), recurrence schedules (20). Referenced by id only.\n// Task activity, version history and audit log are written to audit_events.\n// =====================================================================\n\n/// 06 §3 — semantic category of a configurable task status.\nenum TaskStatusCategory {\n  BACKLOG\n  TODO\n  IN_PROGRESS\n  IN_REVIEW\n  BLOCKED\n  DONE\n  CANCELLED\n}\n\n/// 06 §3\nenum TaskPriority {\n  NONE\n  LOW\n  MEDIUM\n  HIGH\n  URGENT\n}\n\n/// 06 §3 — task-to-task dependency kinds.\nenum TaskDependencyType {\n  BLOCKS\n  RELATED\n  DUPLICATE_OF\n}\n\n/// 06 §4 — cycles / sprints.\nenum CycleStatus {\n  PLANNED\n  ACTIVE\n  COMPLETED\n  CANCELLED\n}\n\n/// 06 §9\nenum ReleaseStatus {\n  PLANNED\n  IN_PROGRESS\n  RELEASED\n  CANCELLED\n}\n\nenum DeploymentStatus {\n  PENDING\n  IN_PROGRESS\n  SUCCEEDED\n  FAILED\n  ROLLED_BACK\n}\n\n/// 06 §7 — comment visibility.\nenum TaskCommentVisibility {\n  INTERNAL\n  CUSTOMER_VISIBLE\n}\n\n// --- Configuration ----------------------------------------------------------------\n\n/// 06 §3 — configurable statuses with workflow transitions. Scoped to a Team when team_id is set,\n/// otherwise organization-wide.\nmodel TaskStatus {\n  id                  String             @id @default(uuid())\n  organization_id     String\n  team_id             String?\n  name                String\n  slug                String\n  category            TaskStatusCategory\n  color               String?\n  sort_order          Int                @default(0)\n  is_default          Boolean            @default(false)\n  /// Slugs this status may transition to; empty = any.\n  allowed_transitions String[]           @default([])\n  archived_at         DateTime?\n  created_at          DateTime           @default(now())\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  team         Team?        @relation(fields: [team_id], references: [id], onDelete: Cascade)\n  tasks        Task[]\n\n  @@unique([organization_id, team_id, slug])\n  @@index([organization_id, category])\n  @@map(\"task_statuses\")\n}\n\n/// 06 §3 — task types (task, bug, feature, improvement, chore, follow-up …).\nmodel TaskType {\n  id              String    @id @default(uuid())\n  organization_id String\n  name            String\n  slug            String\n  icon            String?\n  color           String?\n  is_default      Boolean   @default(false)\n  /// Default field values and checklist for tasks of this type (06 §3 templates).\n  template        Json?\n  sort_order      Int       @default(0)\n  archived_at     DateTime?\n  created_at      DateTime  @default(now())\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  tasks        Task[]\n\n  @@unique([organization_id, slug])\n  @@map(\"task_types\")\n}\n\n/// 06 §3 — Linear-style labels. Platform tags (02 §36) also apply to tasks.\nmodel TaskLabel {\n  id              String    @id @default(uuid())\n  organization_id String\n  name            String\n  slug            String\n  color           String?\n  /// Optional parent for label groups.\n  parent_label_id String?\n  archived_at     DateTime?\n  created_at      DateTime  @default(now())\n\n  organization Organization          @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  parent       TaskLabel?            @relation(\"TaskLabelGroup\", fields: [parent_label_id], references: [id], onDelete: SetNull)\n  children     TaskLabel[]           @relation(\"TaskLabelGroup\")\n  assignments  TaskLabelAssignment[]\n\n  @@unique([organization_id, slug])\n  @@map(\"task_labels\")\n}\n\n/// 06 §4 — cycles / sprints, per team or project.\nmodel Cycle {\n  id              String      @id @default(uuid())\n  organization_id String\n  team_id         String?\n  project_id      String?\n  number          Int\n  name            String?\n  goal            String?\n  status          CycleStatus @default(PLANNED)\n  starts_at       DateTime    @db.Date\n  ends_at         DateTime    @db.Date\n  completed_at    DateTime?\n  created_at      DateTime    @default(now())\n  updated_at      DateTime    @updatedAt\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  team         Team?        @relation(fields: [team_id], references: [id], onDelete: Cascade)\n  project      Project?     @relation(fields: [project_id], references: [id], onDelete: Cascade)\n  tasks        Task[]\n\n  @@unique([organization_id, team_id, number])\n  @@index([organization_id, status])\n  @@map(\"cycles\")\n}\n\n// --- Task ---------------------------------------------------------------------------\n\n/// 06 §3 — the Task record. Work hierarchy: Organization → Team → Project → Workstream/Milestone →\n/// Task → Subtask. Project is optional for personal and CRM work.\nmodel Task {\n  id                         String       @id @default(uuid())\n  organization_id            String\n  /// Sequential per organization; shown with the team key (e.g. ENG-123).\n  number                     Int\n  team_id                    String?\n  project_id                 String?\n  workstream_id              String?\n  milestone_id               String?\n  parent_task_id             String?\n  cycle_id                   String?\n  release_id                 String?\n  type_id                    String?\n  status_id                  String?\n  title                      String\n  /// Markdown body.\n  description                String?\n  priority                   TaskPriority @default(NONE)\n  assignee_membership_id     String?\n  reporter_membership_id     String?\n  estimate_points            Decimal?     @db.Decimal(6, 2)\n  estimate_hours             Decimal?     @db.Decimal(8, 2)\n  start_date                 DateTime?    @db.Date\n  due_date                   DateTime?    @db.Date\n  completed_at               DateTime?\n  cancelled_at               DateTime?\n  /// Acceptance criteria as a checklist-like list: [{ text, done }].\n  acceptance_criteria        Json?\n  /// Visible in the Customer Portal (05 §60, 07 §4).\n  customer_visible           Boolean      @default(false)\n  /// Recurring task instance: schedule rule lives in the Automation Engine (20); the template task is linked.\n  automation_rule_id         String?\n  recurring_template_task_id String?\n  is_template                Boolean      @default(false)\n  /// Lexicographic rank for manual ordering in boards/backlog.\n  rank                       String?\n  /// Duplicate detection target (06 §3).\n  duplicate_of_task_id       String?\n  blocked                    Boolean      @default(false)\n  archived_at                DateTime?\n  created_by_user_id         String?\n  created_at                 DateTime     @default(now())\n  updated_at                 DateTime     @updatedAt\n\n  organization        Organization       @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  team                Team?              @relation(fields: [team_id], references: [id], onDelete: SetNull)\n  project             Project?           @relation(fields: [project_id], references: [id], onDelete: SetNull)\n  workstream          ProjectWorkstream? @relation(fields: [workstream_id], references: [id], onDelete: SetNull)\n  milestone           ProjectMilestone?  @relation(fields: [milestone_id], references: [id], onDelete: SetNull)\n  parent              Task?              @relation(\"TaskHierarchy\", fields: [parent_task_id], references: [id], onDelete: SetNull)\n  subtasks            Task[]             @relation(\"TaskHierarchy\")\n  cycle               Cycle?             @relation(fields: [cycle_id], references: [id], onDelete: SetNull)\n  release             Release?           @relation(fields: [release_id], references: [id], onDelete: SetNull)\n  type                TaskType?          @relation(fields: [type_id], references: [id], onDelete: SetNull)\n  status              TaskStatus?        @relation(fields: [status_id], references: [id], onDelete: SetNull)\n  assignee            Membership?        @relation(\"TaskAssignee\", fields: [assignee_membership_id], references: [id], onDelete: SetNull)\n  reporter            Membership?        @relation(\"TaskReporter\", fields: [reporter_membership_id], references: [id], onDelete: SetNull)\n  recurring_template  Task?              @relation(\"TaskRecurringTemplate\", fields: [recurring_template_task_id], references: [id], onDelete: SetNull)\n  recurring_instances Task[]             @relation(\"TaskRecurringTemplate\")\n  duplicate_of        Task?              @relation(\"TaskDuplicate\", fields: [duplicate_of_task_id], references: [id], onDelete: SetNull)\n  duplicates          Task[]             @relation(\"TaskDuplicate\")\n\n  assignees         TaskAssignee[]\n  labels            TaskLabelAssignment[]\n  dependencies_from TaskDependency[]      @relation(\"TaskDependencySource\")\n  dependencies_to   TaskDependency[]      @relation(\"TaskDependencyTarget\")\n  checklist_items   TaskChecklistItem[]\n  comments          TaskComment[]\n  attachments       TaskAttachment[]\n  links             TaskLink[]\n  watchers          TaskWatcher[]\n\n  // Back-links from other modules' records that reference this task\n  project_issues          ProjectIssue[]\n  project_change_requests ProjectChangeRequest[]\n  project_checklist_items ProjectChecklistItem[]\n  contract_obligations    ContractObligation[]\n\n  @@unique([organization_id, number])\n  @@index([organization_id, status_id])\n  @@index([project_id, status_id])\n  @@index([assignee_membership_id, status_id])\n  @@index([team_id, cycle_id])\n  @@index([parent_task_id])\n  @@index([milestone_id])\n  @@index([due_date])\n  @@map(\"tasks\")\n}\n\n/// 06 §3 — additional assignees beyond the primary assignee.\nmodel TaskAssignee {\n  task_id       String\n  membership_id String\n  assigned_at   DateTime @default(now())\n\n  task       Task       @relation(fields: [task_id], references: [id], onDelete: Cascade)\n  membership Membership @relation(fields: [membership_id], references: [id], onDelete: Cascade)\n\n  @@id([task_id, membership_id])\n  @@index([membership_id])\n  @@map(\"task_assignees\")\n}\n\nmodel TaskLabelAssignment {\n  task_id  String\n  label_id String\n\n  task  Task      @relation(fields: [task_id], references: [id], onDelete: Cascade)\n  label TaskLabel @relation(fields: [label_id], references: [id], onDelete: Cascade)\n\n  @@id([task_id, label_id])\n  @@index([label_id])\n  @@map(\"task_label_assignments\")\n}\n\n/// 06 §3 — blocks / related / duplicates between tasks, including cross-project links.\nmodel TaskDependency {\n  id                 String             @id @default(uuid())\n  source_task_id     String\n  target_task_id     String\n  type               TaskDependencyType @default(BLOCKS)\n  created_by_user_id String?\n  created_at         DateTime           @default(now())\n\n  source Task @relation(\"TaskDependencySource\", fields: [source_task_id], references: [id], onDelete: Cascade)\n  target Task @relation(\"TaskDependencyTarget\", fields: [target_task_id], references: [id], onDelete: Cascade)\n\n  @@unique([source_task_id, target_task_id, type])\n  @@index([target_task_id])\n  @@map(\"task_dependencies\")\n}\n\n/// 06 §3 — checklists inside a task.\nmodel TaskChecklistItem {\n  id                         String    @id @default(uuid())\n  task_id                    String\n  title                      String\n  is_completed               Boolean   @default(false)\n  completed_by_membership_id String?\n  completed_at               DateTime?\n  sort_order                 Int       @default(0)\n\n  task Task @relation(fields: [task_id], references: [id], onDelete: Cascade)\n\n  @@index([task_id])\n  @@map(\"task_checklist_items\")\n}\n\n/// 06 §7 — comments with threads, mentions and reactions. Customer-visible comments surface in 07.\nmodel TaskComment {\n  id                   String                @id @default(uuid())\n  task_id              String\n  parent_comment_id    String?\n  author_membership_id String?\n  /// Customer Portal User (01 §79) when written from the portal; id only.\n  author_user_id       String?\n  visibility           TaskCommentVisibility @default(INTERNAL)\n  body                 String\n  /// Membership ids mentioned.\n  mentions             String[]              @default([])\n  /// { emoji: [membership_id, …] }\n  reactions            Json?\n  edited_at            DateTime?\n  deleted_at           DateTime?\n  created_at           DateTime              @default(now())\n  updated_at           DateTime              @updatedAt\n\n  task    Task          @relation(fields: [task_id], references: [id], onDelete: Cascade)\n  parent  TaskComment?  @relation(\"TaskCommentThread\", fields: [parent_comment_id], references: [id], onDelete: Cascade)\n  replies TaskComment[] @relation(\"TaskCommentThread\")\n  author  Membership?   @relation(\"TaskCommentAuthor\", fields: [author_membership_id], references: [id], onDelete: SetNull)\n\n  @@index([task_id, created_at])\n  @@index([parent_comment_id])\n  @@map(\"task_comments\")\n}\n\n/// 06 §8 — attachments are Documents (17); id only until 17 exists.\nmodel TaskAttachment {\n  id               String   @id @default(uuid())\n  task_id          String\n  document_id      String\n  added_by_user_id String?\n  created_at       DateTime @default(now())\n\n  task Task @relation(fields: [task_id], references: [id], onDelete: Cascade)\n\n  @@unique([task_id, document_id])\n  @@map(\"task_attachments\")\n}\n\n/// 06 §13 — polymorphic link from a task to the record it originated from or serves:\n/// CRM records (02 §14), tickets (13 §4), project change requests (05), customer requests (07),\n/// contract obligations (04 §49), employee onboarding (10).\nmodel TaskLink {\n  id                 String           @id @default(uuid())\n  task_id            String\n  entity_type        RecordEntityType\n  entity_id          String\n  /// origin | related | blocks | fixes\n  relation           String           @default(\"related\")\n  created_by_user_id String?\n  created_at         DateTime         @default(now())\n\n  task Task @relation(fields: [task_id], references: [id], onDelete: Cascade)\n\n  @@unique([task_id, entity_type, entity_id])\n  @@index([entity_type, entity_id])\n  @@map(\"task_links\")\n}\n\n/// Members following a task for notifications (14).\nmodel TaskWatcher {\n  task_id       String\n  membership_id String\n  created_at    DateTime @default(now())\n\n  task       Task       @relation(fields: [task_id], references: [id], onDelete: Cascade)\n  membership Membership @relation(fields: [membership_id], references: [id], onDelete: Cascade)\n\n  @@id([task_id, membership_id])\n  @@index([membership_id])\n  @@map(\"task_watchers\")\n}\n\n// --- Releases -----------------------------------------------------------------------\n\n/// 06 §9 — a shippable set of tasks. A Release may map to a Project Milestone (05).\nmodel Release {\n  id                   String        @id @default(uuid())\n  organization_id      String\n  team_id              String?\n  project_id           String?\n  milestone_id         String?\n  name                 String\n  version              String?\n  status               ReleaseStatus @default(PLANNED)\n  target_date          DateTime?     @db.Date\n  released_at          DateTime?\n  /// Release notes (markdown), publishable to the portal (07) and knowledge base (13 §6).\n  notes                String?\n  notes_document_id    String?\n  customer_visible     Boolean       @default(false)\n  /// Customers affected, derived from linked tickets (13 §4); CRM company ids.\n  affected_company_ids String[]      @default([])\n  created_by_user_id   String?\n  created_at           DateTime      @default(now())\n  updated_at           DateTime      @updatedAt\n\n  organization Organization        @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  team         Team?               @relation(fields: [team_id], references: [id], onDelete: SetNull)\n  project      Project?            @relation(fields: [project_id], references: [id], onDelete: SetNull)\n  tasks        Task[]\n  deployments  ReleaseDeployment[]\n\n  @@index([organization_id, status])\n  @@index([project_id])\n  @@map(\"releases\")\n}\n\n/// 06 §9 — deployment status per environment.\nmodel ReleaseDeployment {\n  id                  String           @id @default(uuid())\n  release_id          String\n  /// development | staging | production | custom\n  environment         String\n  status              DeploymentStatus @default(PENDING)\n  url                 String?\n  deployed_by_user_id String?\n  deployed_at         DateTime?\n  /// External reference (CI run, GitHub deployment id, …).\n  external_ref        String?\n  notes               String?\n  created_at          DateTime         @default(now())\n\n  release Release @relation(fields: [release_id], references: [id], onDelete: Cascade)\n\n  @@index([release_id, environment])\n  @@map(\"release_deployments\")\n}\n"
}

